cp7_credit._consumer_root_source_profile:
CREATE OR REPLACE FUNCTION cp7_credit._consumer_root_source_profile_v1(p_sale uuid, p_root uuid, p_leaf uuid, p_actual jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare ch cp7_credit.cohorts;p cp7_credit.recognition_plans;m cp7_credit.initial_return_materializations;
 events jsonb;ordinal_result jsonb;fresh jsonb;actual_i jsonb;expected_i jsonb;c_events jsonb;capacity jsonb;ce cp7_credit.consumption_events;o cp7_credit.initial_refund_operations;
 j erp.journal_entries;lines jsonb;expected_lines jsonb;n bigint;
begin
 if p_sale<>p_root or p_sale<>p_leaf or p_actual->>'sale_id'<>p_sale::text or p_actual->>'root_sale_id'<>p_root::text
  or p_actual->>'current_leaf_id'<>p_leaf::text
 then
  raise exception 'CP7_CREDIT_CURRENT_SOURCE_ROUTE_UNIMPLEMENTED';end if;
 perform cp7_credit.assert_simple_native_base_v1(p_sale);
 events:=cp7_credit.initial_base_events_v1(p_sale);
 ordinal_result:=ow04_ordinal_wrapper.reconcile_v1(cp7_credit.initial_ordinal_input_v1(p_sale));
 if not(ordinal_result->>'arithmetic_supported')::boolean or exists(select 1 from jsonb_array_elements(ordinal_result->'families')f
  where(f->>'has_reconciliation_effect')::boolean)then raise exception 'CP7_CREDIT_CURRENT_ORDINAL_RECONCILIATION_REQUIRED';end if;
 if exists(select 1 from cp7_credit.source_operation_materializations_v1 where sale_id=p_sale)then
  perform cp7_credit.assert_reconciled_source_profile_v1(p_sale,p_actual);return;
 end if;
 select count(*)into n from cp7_credit.cohorts c join cp7_credit.return_families f on f.id=c.family_id where f.family_root_sale_id=p_sale;
 if n=0 then
  perform cp7_credit.assert_zero_excess_v1(events);
  if(p_actual->>'I')::numeric<>0 then raise exception 'CP7_CREDIT_EMPTY_FAMILY_HAS_FINANCIAL_EFFECT';end if;
  return;
 end if;
 for ch in select c.*from cp7_credit.cohorts c join cp7_credit.return_families f on f.id=c.family_id where f.family_root_sale_id=p_sale order by f.family_ordinal,c.id loop
 select *into strict p from cp7_credit.recognition_plans where id=ch.initial_plan_id;
 select *into strict m from cp7_credit.initial_return_materializations where cohort_id=ch.id and plan_id=p.id;
 if p.plan_kind<>'INITIAL'or exists(select 1 from cp7_credit.recognition_plans where cohort_id=ch.id and id<>p.id)
  or cp7_credit_multi.family_preserved_source_v1(p_sale,(select f.family_ordinal from cp7_credit.return_families f where f.id=ch.family_id))is distinct from m.source_snapshot->'preserved_source'
  or cp7_credit_multi.family_before_events_v1(p_sale,(select f.family_ordinal from cp7_credit.return_families f where f.id=ch.family_id))is distinct from p.before_events then
  raise exception 'CP7_CREDIT_RECOGNIZED_SOURCE_MUTATION_UNIMPLEMENTED';end if;
 perform cp7_credit_multi.assert_prior_families_reconciled_v1(p_sale,p.before_events,ch.source_return_id);
 fresh:=ow04_pure_kernel.recognition_plan_v1(p.before_events,cp7_credit.actual_own_return_events_v1(ch.source_return_id));
 if fresh is distinct from p.kernel_result or fresh is distinct from m.actual_kernel
  or p.net_amount is distinct from(fresh->>'net_current_k')::numeric or p.net_amount<0
  or p.net_amount>(m.projection->>'return_amount')::numeric then raise exception 'CP7_CREDIT_CURRENT_SOURCE_TARGET_CHANGED';end if;
 select coalesce(jsonb_agg(cc.kernel_component order by cc.ordinal),'[]')into actual_i from cp7_credit.recognition_components cc where cc.plan_id=p.id;
 if actual_i is distinct from fresh->'components'or(n=1 and(p_actual->>'I')::numeric<>p.net_amount)or(p_actual->>'U')::numeric<>cp7_credit_incoming.incoming_applied_v1(p_sale)then
  raise exception 'CP7_CREDIT_CURRENT_RECOGNITION_TARGET_UNRECONCILED';end if;
 -- Every consumer has its actual immutable operation and exact named inverse.
 for ce in select *from cp7_credit.consumption_events where cohort_id=ch.id order by id loop
  perform cp7_credit.consumer_event_data_v1(ce.id);
 end loop;
 select coalesce(jsonb_agg(jsonb_build_object('id',consumer.id::text,'amount',cp7_credit.cent_text(consumer.amount),'economic_date',consumer.economic_date::text,
  'transaction_date',consumer.transaction_date::text,'source_sha256',consumer.source_sha256)order by consumer.id),'[]')into c_events from cp7_credit.consumption_events consumer where consumer.cohort_id=ch.id;
 capacity:=ow04_pure_kernel.credit_capacity_v1(cp7_credit.component_movements_v1(fresh),c_events,
  (select min((x->>'economic_date')::date)::text from jsonb_array_elements(fresh->'components')x),
  (select min((x->>'transaction_date')::date)::text from jsonb_array_elements(fresh->'components')x));
 if not(capacity->>'source_prefixes_nonnegative')::boolean then raise exception 'CP7_CREDIT_CURRENT_JOINT_CAPACITY_NEGATIVE';end if;
 end loop;
 if n>1 and((p_actual->>'I')::numeric<>(select coalesce(sum(rp.net_amount),0)from cp7_credit.cohorts c join cp7_credit.return_families f on f.id=c.family_id join cp7_credit.recognition_plans rp on rp.id=c.initial_plan_id where f.family_root_sale_id=p_sale)
  or(ow04_pure_kernel.recognition_plan_v1('[]',events)->>'net_current_k')::numeric<>(select coalesce(sum(rp.net_amount),0)from cp7_credit.cohorts c join cp7_credit.return_families f on f.id=c.family_id join cp7_credit.recognition_plans rp on rp.id=c.initial_plan_id where f.family_root_sale_id=p_sale))then
  raise exception 'CP7_CREDIT_CURRENT_RECOGNITION_TARGET_UNRECONCILED';end if;
end $function$

cp7_credit._post_journal_bound(text,uuid:
CREATE OR REPLACE FUNCTION cp7_credit._post_journal_bound(p_source_type text, p_source_id uuid, p_transaction_date date, p_description text, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_entry_id uuid;
  v_input_debit numeric;
  v_input_credit numeric;
  v_cent_lines jsonb := '[]'::jsonb;
  v_number text;
  v_debit numeric(20,2);
  v_credit numeric(20,2);
  r jsonb;
  v_account_id uuid;
  v_gl_date date;
  v_ap_vendor_account uuid;
  v_vendor_id uuid;
  v_vendor_balance numeric(24,6);
  v_vendor_delta numeric(24,6);
begin
  perform cp7_credit.assert_bound_post(p_source_type,p_source_id,p_transaction_date,p_lines);
  perform erp.require_internal();
  if jsonb_typeof(p_lines) is distinct from 'array' then
    raise exception 'JOURNAL_LINES_ARRAY_REQUIRED';
  end if;
  if jsonb_array_length(p_lines)<2 then
    raise exception 'Journal requires at least two lines';
  end if;
  -- Canonicalize each monetary line exactly as it will be stored. All balance
  -- and vendor-admission checks below consume these same cent amounts.
  for r in select * from jsonb_array_elements(p_lines) loop
    if jsonb_typeof(r) is distinct from 'object' then
      raise exception 'JOURNAL_LINE_OBJECT_REQUIRED';
    end if;
    v_input_debit:=coalesce((r->>'debit')::numeric,0);
    v_input_credit:=coalesce((r->>'credit')::numeric,0);
    if v_input_debit::text in('NaN','Infinity','-Infinity')
       or v_input_credit::text in('NaN','Infinity','-Infinity')
       or v_input_debit<0 or v_input_credit<0 then
      raise exception 'JOURNAL_FINITE_NONNEGATIVE_MONEY_REQUIRED';
    end if;
    v_cent_lines:=v_cent_lines||jsonb_build_array(r||jsonb_build_object(
      'debit',round(v_input_debit,2),'credit',round(v_input_credit,2)));
  end loop;
  p_lines:=v_cent_lines;
  select coalesce(sum(coalesce((x->>'debit')::numeric,0)),0),coalesce(sum(coalesce((x->>'credit')::numeric,0)),0)
  into v_debit,v_credit from jsonb_array_elements(p_lines) x;
  if v_debit<>v_credit or v_debit<=0 then raise exception 'Journal is not balanced. Debit %, Credit %',v_debit,v_credit; end if;
  if exists(select 1 from erp.journal_entries where source_type=p_source_type and source_id=p_source_id and status='POSTED') then
    raise exception 'A posted journal already exists for this source';
  end if;

  -- Serialize journal posting with accounting close/reopen. A close that starts
  -- first blocks this journal until the new closed-through date is visible; a
  -- journal that starts first keeps the close waiting until this posting commits.
  perform 1 from erp.accounting_period_control where singleton_id=1 for share;

  -- Vendor AP is allowed to reach zero, but not become negative. Negative AP
  -- means the company has a receivable/advance from the vendor and requires a
  -- separate explicit workflow instead of silently crossing the account sign.
  v_ap_vendor_account:=erp.account_id('AP_VENDOR');
  for v_vendor_id in
    select distinct nullif(x->>'vendor_id','')::uuid
    from jsonb_array_elements(p_lines) x
    where nullif(x->>'vendor_id','') is not null
      and coalesce((x->>'debit')::numeric,0)>coalesce((x->>'credit')::numeric,0)
      and (
        (x ? 'mapping_key' and x->>'mapping_key'='AP_VENDOR')
        or (x ? 'account_id' and nullif(x->>'account_id','')::uuid=v_ap_vendor_account)
      )
    order by 1
  loop
    perform pg_advisory_xact_lock(hashtextextended('VENDOR_AP|'||v_vendor_id::text,0));

    select coalesce(sum(jl.credit-jl.debit),0)
      into v_vendor_balance
    from erp.journal_lines jl
    join erp.journal_entries je on je.id=jl.journal_entry_id
    where je.status in ('POSTED','REVERSED')
      and jl.account_id=v_ap_vendor_account
      and jl.vendor_id=v_vendor_id;

    select coalesce(sum(
      coalesce((x->>'credit')::numeric,0)-coalesce((x->>'debit')::numeric,0)
    ),0)
      into v_vendor_delta
    from jsonb_array_elements(p_lines) x
    where nullif(x->>'vendor_id','')::uuid=v_vendor_id
      and (
        (x ? 'mapping_key' and x->>'mapping_key'='AP_VENDOR')
        or (x ? 'account_id' and nullif(x->>'account_id','')::uuid=v_ap_vendor_account)
      );

    if v_vendor_balance::text in('NaN','Infinity','-Infinity') or v_vendor_balance+v_vendor_delta < 0 then
      raise exception 'Transaksi ini membuat hutang vendor menjadi negatif. Hutang saat ini %, perubahan %, hasil %. Reverse/koreksi pembayaran, claim, atau invoice terkait dulu; kelebihan bayar/claim vendor harus masuk workflow piutang vendor terpisah.',
        round(v_vendor_balance,2),round(v_vendor_delta,2),round(v_vendor_balance+v_vendor_delta,2);
    end if;
  end loop;

  v_gl_date:=cp7_credit.bound_book_date(p_source_type,p_source_id,p_transaction_date,p_lines);
  v_number:='JRN-'||to_char((clock_timestamp() AT TIME ZONE 'Asia/Jakarta'),'YYYYMMDDHH24MISSMS')||'-'||substr(gen_random_uuid()::text,1,8);
  insert into erp.journal_entries(journal_number,economic_date,transaction_date,posting_at,source_type,source_id,description,status,created_by)
  values(v_number,p_transaction_date,v_gl_date,statement_timestamp(),p_source_type,p_source_id,p_description,'POSTED',erp.current_app_user_id()) returning id into v_entry_id;

  for r in select * from jsonb_array_elements(p_lines) loop
    if r?'account_id' then v_account_id:=(r->>'account_id')::uuid; else v_account_id:=erp.account_id(r->>'mapping_key'); end if;
    insert into erp.journal_lines(journal_entry_id,account_id,description,debit,credit,customer_id,vendor_id,contractor_id,po_id,product_id)
    values(v_entry_id,v_account_id,r->>'description',coalesce((r->>'debit')::numeric,0),coalesce((r->>'credit')::numeric,0),nullif(r->>'customer_id','')::uuid,nullif(r->>'vendor_id','')::uuid,nullif(r->>'contractor_id','')::uuid,nullif(r->>'po_id','')::uuid,nullif(r->>'product_id','')::uuid);
  end loop;

  insert into erp.account_daily_balances(balance_date,account_id,debit_total,credit_total)
  select v_gl_date,jl.account_id,sum(jl.debit),sum(jl.credit) from erp.journal_lines jl where jl.journal_entry_id=v_entry_id group by jl.account_id
  on conflict(balance_date,account_id) do update set debit_total=erp.account_daily_balances.debit_total+excluded.debit_total,credit_total=erp.account_daily_balances.credit_total+excluded.credit_total,updated_at=statement_timestamp();

  if v_gl_date<>p_transaction_date then
    insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
    values('journal_entries',v_entry_id,'POST',(jsonb_build_object('economic_date',p_transaction_date,'transaction_date',v_gl_date,'period_shifted',true,'source_type',p_source_type,'source_id',p_source_id)||cp7_credit.bound_audit_context()),erp.current_app_user_id(),'OW04 derived book date: lawful open period and source-bound dated profile');
  end if;
  return v_entry_id;
end;
$function$

cp7_credit.assert_consumer_closed_v1(uui:
CREATE OR REPLACE FUNCTION cp7_credit.assert_consumer_closed_v1(p_operation uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare o cp7_credit.consumer_operations_v1;c cp7_credit.consumer_completions_v1;q cp7_credit.consumer_requests_v1;
 e cp7_credit.consumption_events;manifest jsonb;expected jsonb;profiles jsonb;profile jsonb;before_profile jsonb;native jsonb;
 sale text;net numeric;paid numeric;incoming numeric;issued numeric;effective numeric;after_version bigint;vectors jsonb;capacity jsonb;
begin
 perform cp7_credit.assert_consumer_operation_input_v1(p_operation);
 select *into strict o from cp7_credit.consumer_operations_v1 where id=p_operation;
 select *into strict c from cp7_credit.consumer_completions_v1 where operation_id=o.id;
 select *into strict q from cp7_credit.consumer_requests_v1 where actor=o.actor and request_id=o.request_id;
 select *into strict e from cp7_credit.consumption_events where id=o.id;
 manifest:=cp7_credit.consumer_actual_manifest_v1(o.id);
 profiles:=c.final_profiles->'invoices';
 expected:=cp7_credit.consumer_outcome_v1(o.id,profiles,c.final_profiles->'source_capacity');
 if(q.action,q.payload->>'quote_sha256',cp7_credit.pg_jsonb_sha256(q.payload),q.expected_versions,q.response)
   is distinct from(o.action,o.quote_sha256,o.payload_sha256,o.projection->'expected_versions',expected)
  or c.response is distinct from expected
  or(c.consumption_event_id,c.journal_id,c.materialization_id,c.journal_lines_sha256_pg)is distinct from
   (e.id,e.journal_id,o.id,e.lines_sha256_pg)
  or c.actual_manifest is distinct from manifest or c.actual_manifest_sha256<>cp7_credit.pg_jsonb_sha256(manifest)
  or c.final_native is distinct from o.before_native
  or o.quote_sha256<>cp7_credit.consumer_quote_binding_v1(q.payload,o.locked_sources,o.projection)
  or cp7_credit.consumer_verify_posted_journal_v1(o.id,e.journal_id)<>e.lines_sha256_pg then
  raise exception 'CP7_CREDIT_CONSUMER_HISTORICAL_COMPLETION_CHANGED';end if;
 if (select jsonb_agg(key order by key)from jsonb_object_keys(profiles)key)is distinct from o.source_graph->'sale_ids'then
  raise exception 'CP7_CREDIT_CONSUMER_FINAL_INVOICE_SET_CHANGED';end if;
 for sale in select value from jsonb_array_elements_text(o.source_graph->'sale_ids')order by value loop
  profile:=profiles->sale;before_profile:=o.locked_sources#>array['sources',sale,'profile'];
  native:=o.locked_sources#>array['sources',sale,'native'];
  select coalesce(sum((v->>'line_total')::numeric),0)into net from jsonb_array_elements(native->'items')v;
  net:=net-(select coalesce(sum((v->>'refund_amount')::numeric),0)from jsonb_array_elements(native->'return_items')v
   where exists(select 1 from jsonb_array_elements(native->'returns')r where r->>'id'=v->>'return_id'and r->>'status'='POSTED'));
  select coalesce(sum((v->>'amount')::numeric),0)into paid from jsonb_array_elements(native->'payments')v where v->>'status'='POSTED';
  issued:=(before_profile->>'I')::numeric;incoming:=(before_profile->>'U')::numeric;
  if sale=o.target_sale_id::text then incoming:=incoming+o.amount;end if;
  effective:=paid+incoming-issued;
  after_version:=(o.projection#>>array['expected_versions',sale])::bigint
   +case when sale in(o.source_current_leaf_id::text,o.target_current_leaf_id::text)then 1 else 0 end;
  if profile->>'sale_id'<>sale or(profile->>'row_version')::bigint is distinct from after_version
   or(profile->>'net')::numeric is distinct from net or(profile->>'P')::numeric is distinct from paid
   or(profile->>'U')::numeric is distinct from incoming or(profile->>'I')::numeric is distinct from issued
   or(profile->>'E')::numeric is distinct from effective or(profile->>'AR')::numeric is distinct from net-effective
   or profile->>'status'is distinct from(case when effective=net then'PAID'when effective>0 then'PARTIAL_PAID'else'POSTED'end)
   or net<0 or effective<0 or effective>net then raise exception 'CP7_CREDIT_CONSUMER_HISTORICAL_FINANCIAL_EFFECT_CHANGED';end if;
  perform cp7_credit.assert_financial_materialization_provenance(profile->'materialized');
  -- Current validation follows all retained signed events and every joint cut.
  perform cp7_credit.consumer_invoice_profile_v1(sale::uuid);
 end loop;
 if c.final_profiles#>>'{source_capacity,source_prefixes_nonnegative}'is distinct from'true'
  or(c.final_profiles#>>'{source_capacity,current_balance}')::numeric is distinct from(o.projection#>>'{source_capacity_after,current_balance}')::numeric
  or(c.final_profiles#>>'{source_capacity,minimum_available}')::numeric is distinct from(o.projection#>>'{source_capacity_after,minimum_available}')::numeric then
  raise exception 'CP7_CREDIT_CONSUMER_HISTORICAL_CAPACITY_CHANGED';end if;
 if o.cash_coa_account_id is not null then
  if(c.final_profiles->>'cash_balance_after')::numeric is distinct from(o.projection->>'cash_balance_before')::numeric-o.amount then
   raise exception 'CP7_CREDIT_CONSUMER_HISTORICAL_CASH_EFFECT_CHANGED';end if;
 elsif c.final_profiles->>'cash_balance_after'is not null then raise exception 'CP7_CREDIT_CONSUMER_UNEXPECTED_CASH_EFFECT';end if;
 vectors:=cp7_credit.consumer_source_vectors_v1(o.cohort_id);
 capacity:=ow04_pure_kernel.credit_capacity_v1(vectors->'recognition',vectors->'consumptions',o.economic_date::text,o.transaction_date::text);
 if capacity->'source_prefixes_nonnegative'is distinct from'true'::jsonb then
  raise exception 'CP7_CREDIT_CONSUMER_CURRENT_HISTORICAL_JOINT_CAPACITY_UNFUNDED';end if;
 -- Leak checks are transaction facts, with no live-actor permission dependency.
 if exists(select 1 from cp7_credit.consumer_execution_context where backend_pid=pg_backend_pid()and transaction_id=txid_current())
  or exists(select 1 from cp7_credit.consumer_posting_scope_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current())then
  raise exception 'CP7_CREDIT_CONSUMER_TEMPORARY_SCOPE_NOT_CLEARED';end if;
end $function$

cp7_credit.assert_current_source_plan_pr:
CREATE OR REPLACE FUNCTION cp7_credit.assert_current_source_plan_profile(p_sale uuid, p_root uuid, p_leaf uuid, p_actual jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare root uuid;actual jsonb;e record;
begin
 if(p_actual->>'sale_id',p_actual->>'root_sale_id',p_actual->>'current_leaf_id')is distinct from
   (p_sale::text,p_root::text,p_leaf::text)then raise exception 'CP7_CREDIT_CURRENT_ASSIGNMENT_CHANGED';end if;
 if jsonb_typeof(p_actual->'upstream_root_ids')is distinct from'array'
  or not(p_actual->'upstream_root_ids')@>jsonb_build_array(p_root)then raise exception 'CP7_CREDIT_CURRENT_SOURCE_ROOT_SET_REQUIRED';end if;
 for root in select value::uuid from jsonb_array_elements_text(p_actual->'upstream_root_ids')order by value loop
  actual:=case when root=p_root then p_actual else cp7_credit.current_materialized_objects(root,root,root)end;
  for e in select ce.id from cp7_credit.consumption_events ce join cp7_credit.cohorts c on c.id=ce.cohort_id
   join cp7_credit.return_families f on f.id=c.family_id where f.family_root_sale_id=root order by ce.id loop
   perform cp7_credit.consumer_event_data_v1(e.id);
  end loop;
  perform cp7_credit._consumer_root_source_profile_v1(root,root,root,actual);
 end loop;
end $function$

cp7_credit.assert_financial_materializat:
CREATE OR REPLACE FUNCTION cp7_credit.assert_financial_materialization_provenance(p_actual jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare marker_id uuid;f cp7_credit.financial_materializations;m cp7_credit.initial_return_materializations;o cp7_credit.initial_refund_operations;
begin
 perform cp7_credit.assert_native_empty_provenance_v1(p_actual);
 p_actual:=cp7_credit.without_native_empty_markers_v1(p_actual);
 for marker_id in select value::uuid from jsonb_array_elements_text(p_actual->'materialization_ids')loop
  select fm.*into strict f from cp7_credit.financial_materializations fm where fm.id=marker_id;
  select *into m from cp7_credit.initial_return_materializations where materialization_id=f.id;
  if m.operation_id is not null then
   if(f.root_sale_id,f.actor,f.request_id,f.request_ordinal,f.payload_sha256,f.source_plan_sha256)is distinct from
    (m.source_sale_id,m.actor,m.request_id,1,m.payload_sha256,m.projection_sha256)
    or f.owning_action<>(case when m.origin='ORDINARY'then'RETURN'else'RETURN_SETTLEMENT'end)
    or m.projection_sha256 is distinct from ow04_source_proposal.sha(m.projection)
    or m.projection_actual_proof_sha256 is distinct from ow04_source_proposal.sha(m.projection_actual_proof)
    or m.prior_causal->>'proof_sha256'is distinct from ow04_source_proposal.sha(m.prior_causal_manifest)
    or not exists(select 1 from cp7_credit.return_families rf where rf.id=m.family_id and rf.first_return_id=m.source_return_id
     and rf.family_ordinal=m.family_ordinal and rf.actor=m.actor and rf.request_id=m.request_id)then
    raise exception 'CP7_CREDIT_INITIAL_PROVENANCE_CHANGED';end if;
  elsif exists(select 1 from cp7_credit.source_operation_materializations_v1 where financial_marker_id=f.id)then
   perform cp7_credit.assert_source_materialization_v1((select operation_id from cp7_credit.source_operation_materializations_v1 where financial_marker_id=f.id));
  elsif exists(select 1 from cp7_credit.consumer_operations_v1 where id=f.id)then
   perform cp7_credit.consumer_actual_manifest_v1(f.id);
  else
   select *into strict o from cp7_credit.initial_refund_operations where id=f.id;
   select *into strict m from cp7_credit.initial_return_materializations where refund_operation_id=o.id;
   if(f.root_sale_id,f.actor,f.request_id,f.request_ordinal,f.owning_action,f.payload_sha256,f.source_plan_sha256)is distinct from
    (m.source_sale_id,m.actor,m.request_id,o.materialization_ordinal,'RETURN_SETTLEMENT',m.payload_sha256,m.projection_sha256)
    or not exists(select 1 from cp7_credit.consumption_events ce where ce.id=o.id and ce.cohort_id=m.cohort_id)
    or jsonb_array_length(f.actual_objects)<>1 or f.actual_objects->0->>'object_kind'<>'CONSUMPTION'
    or f.actual_objects->0->>'object_id'<>o.id::text then raise exception 'CP7_CREDIT_REFUND_PROVENANCE_CHANGED';end if;
  end if;
 end loop;
end $function$

cp7_credit.assert_simple_native_base_v1(:
CREATE OR REPLACE FUNCTION cp7_credit.assert_simple_native_base_v1(p_sale uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare h erp.sales_headers;p erp.sales_payments;f erp.sales_payment_posting_facts;rv erp.sales_payment_reversal_facts;j erp.journal_entries;
 x record;ar uuid;gross numeric;expected numeric;n bigint;inverse erp.journal_entries;fact jsonb;
begin
 select *into strict h from erp.sales_headers where id=p_sale;
 if exists(select 1 from cp7_note.revisions where p_sale in(root_sale_id,previous_sale_id,replacement_sale_id))
  or exists(select 1 from cp7_sales_return_correction.links where sale_id=p_sale)then
  raise exception 'CP7_CREDIT_SOURCE_CORRECTION_ADAPTER_UNIMPLEMENTED'using detail=cp7_credit_followups.correction_reasons_v1(p_sale);end if;
 perform cp7_credit.payment_link_source_check_v1(p_sale);
 ar:=cp7_credit.account_by_mapping_v1('AR_CUSTOMER');
 select coalesce(sum(line_total),0)into gross from erp.sales_items where sale_id=h.id;
 if gross<0 then raise exception 'CP7_CREDIT_CORRUPT_SALE_TOTAL';end if;
 select count(*)into n from erp.journal_entries where source_type='SALE'and source_id=h.id and reversal_of_id is null;
 if n=0 then perform ow04_source_proposal.sale_absence_fact_v1(h.id);
 elsif n<>1 then raise exception 'CP7_CREDIT_NATIVE_SALE_JOURNAL_COUNT';
 else
  select *into strict j from erp.journal_entries where source_type='SALE'and source_id=h.id and reversal_of_id is null;
  if j.economic_date<>(h.sale_date at time zone'Asia/Jakarta')::date or j.transaction_date<j.economic_date
   or j.status<>(case when h.status='REVERSED'then'REVERSED'else'POSTED'end)
   or coalesce((select sum(debit-credit)from erp.journal_lines where journal_entry_id=j.id and account_id=ar),0)<>gross
   or(select count(*)from erp.journal_lines where journal_entry_id=j.id and account_id=ar)<>(case when gross=0 then 0 else 1 end)then
   raise exception 'CP7_CREDIT_NATIVE_SALE_AR_OR_PAIR_CHANGED';end if;
 end if;
 for p in select *from erp.sales_payments where sale_id=p_sale and status<>'DRAFT'order by id loop
  select *into strict f from erp.sales_payment_posting_facts where payment_id=p.id;
  select *into strict j from erp.journal_entries where id=f.original_journal_entry_id;
  if p.status not in('POSTED','REVERSED')or p.amount<=0 or p.amount*100<>trunc(p.amount*100)
   or f.sale_id<>p_sale or f.customer_id<>h.customer_id or f.payment_snapshot is distinct from to_jsonb(p)-'status'
   or(f.payment_number,f.payment_date,f.amount,f.cash_account_id,f.replaces_payment_id)is distinct from
    (p.payment_number,p.payment_date,p.amount,p.cash_account_id,p.replaces_payment_id)
   or f.replaces_payment_id is not null or f.predecessor_reversal_journal_id is not null
   or(j.source_type,j.source_id,j.reversal_of_id,j.economic_date,j.transaction_date,j.posting_at)is distinct from
    ('SALES_PAYMENT',p.id,null::uuid,f.journal_economic_date,f.journal_transaction_date,f.journal_posting_at)
   or j.economic_date<>(p.payment_date at time zone'Asia/Jakarta')::date or j.transaction_date<j.economic_date
   or j.status<>(case when p.status='REVERSED'then'REVERSED'else'POSTED'end)
   or f.lineage_sha256 is distinct from ow04_source_proposal.native_sha(jsonb_build_array(f.payment_id,f.sale_id,f.customer_id,
    f.payment_number,f.payment_date,f.amount,f.cash_account_id,f.original_journal_entry_id,f.journal_economic_date,f.journal_transaction_date,
    f.journal_posting_at,f.replaces_payment_id,f.predecessor_reversal_journal_id,f.payment_snapshot))
   or(select count(*)from erp.journal_lines where journal_entry_id=j.id and account_id=ar)<>1
   or not exists(select 1 from erp.journal_lines where journal_entry_id=j.id and account_id=ar and customer_id=h.customer_id and debit=0 and credit=p.amount
    and vendor_id is null and contractor_id is null and po_id is null and product_id is null)then
   raise exception 'CP7_CREDIT_NATIVE_PAYMENT_FACT_CHANGED';end if;
  if p.cash_account_id is null then
   if p.payment_method<>'OPENING_ADVANCE'or not exists(select 1 from erp.initial_import_prepayment_payments l
    join erp.initial_import_prepayments a on a.id=l.advance_id where l.payment_id=p.id and l.sales_payment_id=p.id
     and l.payment_snapshot=to_jsonb(p)-'status'and a.party_type='CUSTOMER'and a.party_id=h.customer_id
     and exists(select 1 from erp.journal_lines jl where jl.journal_entry_id=j.id and jl.account_id=a.coa_account_id
      and jl.customer_id=h.customer_id and jl.debit=p.amount and jl.credit=0))then
    raise exception 'CP7_CREDIT_NATIVE_ADVANCE_FUNDING_FACT_CHANGED';end if;
  elsif not exists(select 1 from erp.cash_accounts c join erp.journal_lines jl on jl.account_id=c.coa_account_id
   where c.id=p.cash_account_id and jl.journal_entry_id=j.id and jl.customer_id=h.customer_id and jl.debit=p.amount and jl.credit=0)then
   raise exception 'CP7_CREDIT_NATIVE_CASH_FUNDING_FACT_CHANGED';end if;
  select *into rv from erp.sales_payment_reversal_facts where payment_id=p.id;
  if(p.status='REVERSED')<>(rv.payment_id is not null)then raise exception 'CP7_CREDIT_NATIVE_PAYMENT_REVERSAL_FACT_CHANGED';end if;
  if rv.payment_id is not null then
   select *into strict inverse from erp.journal_entries where id=rv.reversal_journal_entry_id;
   if rv.original_journal_entry_id<>j.id
    or(inverse.source_type,inverse.source_id,inverse.reversal_of_id,inverse.economic_date,inverse.transaction_date,inverse.posting_at)is distinct from
     ('JOURNAL_REVERSAL',j.id,j.id,rv.reversal_economic_date,rv.reversal_transaction_date,rv.reversal_posting_at)
    or rv.lineage_sha256 is distinct from ow04_source_proposal.native_sha(jsonb_build_array(rv.payment_id,rv.original_journal_entry_id,
     rv.reversal_journal_entry_id,rv.reversal_economic_date,rv.reversal_transaction_date,rv.reversal_posting_at))then
    raise exception 'CP7_CREDIT_NATIVE_PAYMENT_REVERSAL_FACT_CHANGED';end if;
  end if;
 end loop;
 for x in select r.id from erp.sales_returns r where r.sale_id=p_sale and r.status<>'DRAFT'order by r.id loop
  perform ow04_source_proposal.verify_return_member_v1(x.id);
 end loop;
 -- All real original/inverse legs must be balanced with the exact inverse
 -- vector and both source floors. Unknown restatement/correction routes refuse.
 for x in select ev from jsonb_array_elements(cp7_credit.initial_base_events_v1(p_sale))ev loop
  select *into strict j from erp.journal_entries where id=substring(x.ev->>'id'from 9)::uuid;
  if j.transaction_date<j.economic_date or not exists(select 1 from erp.journal_lines l where l.journal_entry_id=j.id
   group by l.journal_entry_id having sum(l.debit)=sum(l.credit)and sum(l.debit)>0)
   or exists(select 1 from erp.journal_lines l where l.journal_entry_id=j.id and(l.debit<0 or l.credit<0
    or l.debit::text in('NaN','Infinity','-Infinity')or l.credit::text in('NaN','Infinity','-Infinity')))
   or exists(select 1 from erp.journal_lines l where l.journal_entry_id=j.id and l.account_id=ar and l.customer_id is distinct from h.customer_id)then
   raise exception 'CP7_CREDIT_NATIVE_BASE_JOURNAL_INVALID';end if;
  select count(*)into n from erp.journal_entries ji where ji.source_type='JOURNAL_REVERSAL'and(ji.source_id=j.id or ji.reversal_of_id=j.id);
  if j.status='REVERSED'and n<>1 or j.status='POSTED'and n<>0 then raise exception 'CP7_CREDIT_NATIVE_INVERSE_COMPLETENESS_REQUIRED';end if;
  if j.source_type='JOURNAL_REVERSAL'then
   select *into strict inverse from erp.journal_entries where id=j.reversal_of_id;
   if j.source_id<>inverse.id or inverse.status<>'REVERSED'or j.economic_date<inverse.economic_date or j.transaction_date<inverse.transaction_date
    or cp7_credit.initial_line_semantics_v1((select jsonb_agg(jsonb_build_object('account_id',l.account_id,'customer_id',l.customer_id,
     'vendor_id',l.vendor_id,'contractor_id',l.contractor_id,'po_id',l.po_id,'product_id',l.product_id,'debit',l.debit,'credit',l.credit))from erp.journal_lines l where l.journal_entry_id=j.id))
     is distinct from cp7_credit.initial_line_semantics_v1((select jsonb_agg(jsonb_build_object('account_id',l.account_id,'customer_id',l.customer_id,
     'vendor_id',l.vendor_id,'contractor_id',l.contractor_id,'po_id',l.po_id,'product_id',l.product_id,'debit',l.credit,'credit',l.debit))from erp.journal_lines l where l.journal_entry_id=inverse.id))then
    raise exception 'CP7_CREDIT_NATIVE_INVERSE_SOURCE_CHANGED';end if;
  end if;
 end loop;
end $function$

cp7_credit.consumer_capture_sources_v1(j:
CREATE OR REPLACE FUNCTION cp7_credit.consumer_capture_sources_v1(p_graph jsonb)
