cp7_credit.consumer_projection_v1(jsonb,:
CREATE OR REPLACE FUNCTION cp7_credit.consumer_projection_v1(p_payload jsonb, p_locked jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare selection jsonb:=p_locked->'selection';ch cp7_credit.cohorts;old cp7_credit.consumption_events;
 physical timestamptz:=(p_payload->>'physical_at')::timestamptz;economic date;lawful date;floor date;book date;
 amount numeric:=(selection->>'amount')::numeric;vectors jsonb;credit jsonb;cash jsonb;target_ar jsonb;
 capacity jsonb;after_capacity jsonb;added jsonb;book_plan jsonb;target_input jsonb;target_result jsonb;
 source_profile jsonb;target_profile jsonb;projection jsonb;versions jsonb:='{}';sale text;before_native jsonb:='{}';
begin
 select *into strict ch from cp7_credit.cohorts where id=(selection->>'cohort_id')::uuid;
 if not isfinite(physical)or physical>statement_timestamp()
  or physical<(select physical_at from erp.sales_returns where id=ch.source_return_id)then
  raise exception 'CP7_CREDIT_CONSUMER_PHYSICAL_SOURCE_DATE_INVALID';end if;
 economic:=(physical at time zone'Asia/Jakarta')::date;
 lawful:=erp.resolve_accounting_transaction_date(economic);floor:=lawful;
 vectors:=cp7_credit.consumer_source_vectors_v1(ch.id);
 credit:=cp7_credit.credit_account_facts_v1(ch.credit_account_id);
 if selection->>'target_sale_id'is not null then
  target_ar:=cp7_credit.consumer_invoice_ar_source_v1((selection->>'target_sale_id')::uuid);
  if physical<(select sale_date from erp.sales_headers where id=(selection->>'target_sale_id')::uuid)then
   raise exception 'CP7_CREDIT_CONSUMER_PHYSICAL_BEFORE_TARGET';end if;
  floor:=greatest(floor,(target_ar#>>'{financial_source,transaction_date}')::date);
 end if;
 if selection->>'cash_account_id'is not null then
  cash:=cp7_credit.cash_account_facts_v1((selection->>'cash_account_id')::uuid);
  if p_payload->>'action'='UNDO'then
   -- Restoring the same immutable cash account is mandatory; current cash
   -- eligibility/Native dated cash guards remain mandatory as well.
   if (cp7_credit.consumer_event_data_v1((selection->>'restores_event_id')::uuid)->>'other_account_id')
    is distinct from cash#>>'{account,id}'then raise exception 'CP7_CREDIT_CONSUMER_ORIGINAL_CASH_MAPPING_CHANGED';end if;
  end if;
 end if;
 if amount>0 then
  book_plan:=cp7_credit.consumer_positive_credit_book_bound_v1(vectors->'recognition',vectors->'consumptions',amount,physical,lawful,floor,statement_timestamp());
  book:=(book_plan->>'minimum_source_book_date')::date;
 else
  select *into strict old from cp7_credit.consumption_events where id=(selection->>'restores_event_id')::uuid;
  if economic<old.economic_date then raise exception 'CP7_CREDIT_CONSUMER_UNDO_BEFORE_ORIGINAL';end if;
  if exists(select 1 from cp7_credit.consumer_operations_v1 o where o.id=old.id and physical<o.physical_at)
   or exists(select 1 from cp7_credit.initial_refund_operations o where o.id=old.id and physical<o.physical_at)then
   raise exception 'CP7_CREDIT_CONSUMER_UNDO_BEFORE_ORIGINAL_PHYSICAL';end if;
  book:=greatest(floor,old.transaction_date);
  if book>erp._cp3_business_date(statement_timestamp())then raise exception 'CP7_CREDIT_CONSUMER_UNDO_BOOK_IN_FUTURE';end if;
  book_plan:=jsonb_build_object('basis','EXACT_ORIGINAL_AND_CURRENT_NATIVE_LAWFUL_INVERSE',
   'original_event_id',old.id,'original_economic_date',old.economic_date,'original_book_date',old.transaction_date,
   'lawful_book_date',lawful,'source_floor',floor);
 end if;
 book_plan:=book_plan||jsonb_build_object('selected_book_date',book);
 added:=jsonb_build_object('id','consumer-review:'||cp7_credit.pg_jsonb_sha256(p_payload-'quote_sha256'),
  'amount',cp7_credit.cent_text(amount::cp7_credit.cent_amount),'economic_date',economic::text,'transaction_date',book::text,
  'source_sha256',cp7_credit.pg_jsonb_sha256(p_payload-'quote_sha256'));
 after_capacity:=ow04_pure_kernel.credit_capacity_v1(vectors->'recognition',
  (vectors->'consumptions')||jsonb_build_array(added),economic::text,book::text);
 if after_capacity->'source_prefixes_nonnegative'is distinct from'true'::jsonb
  or(after_capacity->>'current_balance')::numeric<0 then raise exception 'CP7_CREDIT_CONSUMER_FINAL_JOINT_CAPACITY_NEGATIVE';end if;
 if selection->>'target_sale_id'is not null then
  target_input:=cp7_credit.initial_ordinal_input_v1((selection->>'target_sale_id')::uuid);
  target_input:=jsonb_set(target_input,'{base_events}',(target_input->'base_events')||jsonb_build_array(added||jsonb_build_object('kind','FUNDING')));
  target_result:=ow04_ordinal_wrapper.reconcile_v1(target_input);
  if target_result->'arithmetic_supported'is distinct from'true'::jsonb
   or exists(select 1 from jsonb_array_elements(target_result->'families')f where(f->>'has_reconciliation_effect')::boolean)then
   raise exception 'CP7_CREDIT_CONSUMER_FAMILY_ADJUSTMENT_REVIEW_REQUIRED';end if;
  target_profile:=p_locked#>array['sources',selection->>'target_sale_id','profile'];
 end if;
 for sale in select value from jsonb_array_elements_text(p_locked#>'{graph,sale_ids}')order by value loop
  versions:=versions||jsonb_build_object(sale,p_locked#>>array['sources',sale,'native','sale','row_version']);
  before_native:=before_native||jsonb_build_object(sale,cp7_credit.consumer_native_invariant_v1(sale::uuid));
 end loop;
 source_profile:=p_locked#>array['sources',selection->>'source_sale_id','profile'];
 projection:=jsonb_build_object('contract_version','ow04.consumer-projection.v1','selection',selection,
  'economic_date',economic,'transaction_date',book,'physical_at',cp7_credit.refund_physical_text(physical),
  'vectors_before',vectors,'signed_added_consumption',added,'source_capacity_after',after_capacity,
  'credit_account',credit,'cash_account',cash,'target_ar_source',target_ar,'book_manifest',book_plan,
  'target_ordinal_after',target_result,'before_source_profile',source_profile,'before_target_profile',target_profile,
  'expected_versions',versions,'before_native',before_native,'locked_lot_ids',p_locked->'locked_lot_ids',
  'locked_hpp_ids',p_locked->'locked_hpp_ids','cash_balance_before',p_locked->'cash_balance_before');
 return projection;
end $function$

cp7_credit.consumer_quote_v1(jsonb):
CREATE OR REPLACE FUNCTION cp7_credit.consumer_quote_v1(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare locked jsonb;projection jsonb;selection jsonb;binding text;
begin
 if current_setting('transaction_isolation')<>'read committed'then raise exception 'CP7_FRESH_ACCESS_REQUIRED';end if;
 perform cp7_credit.validate_consumer_payload_v1(p_payload,false);
 perform cp7_credit.consumer_payload_kind_v1(p_payload);
 perform cp7_credit.assert_no_ambient_native_context();
 perform cp7_credit.assert_consumer_scopes_clear_v1();
 locked:=cp7_credit.consumer_lock_sources_v1(p_payload);
 projection:=cp7_credit.consumer_projection_v1(p_payload,locked);selection:=locked->'selection';
 binding:=cp7_credit.consumer_quote_binding_v1(p_payload,locked,projection);
 return jsonb_build_object('contract_version','cp7.customer-credit-review.v1','read_only',true,
  'selection',selection,'physical_at',projection->'physical_at','economic_date',projection->'economic_date',
  'transaction_date',projection->'transaction_date','book_basis',projection->'book_manifest',
  'available_credit_after',projection#>'{source_capacity_after,current_balance}',
  'expected_versions',projection->'expected_versions','quote_sha256',binding);
end $function$

cp7_credit.consumer_selection_v1(jsonb):
CREATE OR REPLACE FUNCTION cp7_credit.consumer_selection_v1(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare ch cp7_credit.cohorts;old cp7_credit.consumption_events;kind text;amount numeric;
 target uuid;cash uuid;original uuid;source_assignment record;
 target_customer uuid;target_root uuid;target_leaf uuid;target_status text;
begin
 kind:=cp7_credit.consumer_payload_kind_v1(p);
 if p->>'action'='UNDO'then
  select *into strict old from cp7_credit.consumption_events where id=(p->>'restores_event_id')::uuid;
  perform cp7_credit.consumer_event_data_v1(old.id);
  if exists(select 1 from cp7_credit.consumption_events where restores_event_id=old.id)then
   raise exception 'CP7_CREDIT_CONSUMER_ORIGINAL_ALREADY_UNDONE';end if;
  original:=old.id;amount:=-old.amount;target:=old.target_sale_id;cash:=old.cash_account_id;
  select *into strict ch from cp7_credit.cohorts where id=old.cohort_id;
 else
  select *into strict ch from cp7_credit.cohorts where id=(p->>'cohort_id')::uuid;
  amount:=(p->>'amount')::numeric;target:=(p->>'target_sale_id')::uuid;cash:=(p->>'cash_account_id')::uuid;
 end if;
 select *into strict source_assignment from cp7_credit.current_leaf_assignment(ch.source_sale_id);
 if source_assignment.requested_status not in('POSTED','PARTIAL_PAID','PAID')
  or(source_assignment.root_sale_id,source_assignment.current_leaf_id)is distinct from(ch.source_sale_id,ch.source_sale_id)then
  raise exception 'CP7_CREDIT_CONSUMER_SOURCE_CORRECTION_ADAPTER_REQUIRED';end if;
 if target is not null then
  select a.customer_id,a.root_sale_id,a.current_leaf_id,a.requested_status
   into strict target_customer,target_root,target_leaf,target_status from cp7_credit.current_leaf_assignment(target)a;
  if target_customer<>ch.customer_id or target_root=source_assignment.root_sale_id then
   raise exception 'CP7_CREDIT_CONSUMER_DISTINCT_SAME_CUSTOMER_TARGET_REQUIRED';end if;
  if target_status not in('POSTED','PARTIAL_PAID','PAID')
   or(target_root,target_leaf)is distinct from(target,target)then
   raise exception 'CP7_CREDIT_CONSUMER_TARGET_CORRECTION_ADAPTER_REQUIRED';end if;
 end if;
 return jsonb_build_object('action',p->>'action','event_kind',kind,'cohort_id',ch.id,'customer_id',ch.customer_id,
  'source_sale_id',ch.source_sale_id,'source_root_sale_id',source_assignment.root_sale_id,
  'source_current_leaf_id',source_assignment.current_leaf_id,'target_sale_id',target,
  'target_root_sale_id',target_root,
  'target_current_leaf_id',target_leaf,
  'cash_account_id',cash,'restores_event_id',original,'amount',cp7_credit.cent_text(amount::cp7_credit.cent_amount));
end $function$

cp7_credit.current_materialized_objects(:
CREATE OR REPLACE FUNCTION cp7_credit.current_materialized_objects(p_sale uuid, p_root uuid, p_leaf uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare a record;m record;f record;c record;p record;cc record;q record;e record;o record;j erp.journal_entries;
 roots uuid[];next_roots uuid[];sales uuid[];cohorts uuid[];part_ids uuid[]:='{}';journal_ids uuid[]:='{}';
 customer uuid;v_root uuid;v_leaf uuid;objects jsonb:='[]';components jsonb;parts jsonb;canonical jsonb;
 expected_lines jsonb;actual_lines jsonb;state jsonb;v_i numeric:=0;v_u numeric:=0;n bigint;v_sum numeric;
begin
 select *into strict a from cp7_credit.current_leaf_assignment(p_sale);
 if(a.root_sale_id,a.current_leaf_id)is distinct from(p_root,p_leaf)
  or p_sale<>p_leaf or a.requested_status not in('POSTED','PARTIAL_PAID','PAID')then
  raise exception 'CP7_CREDIT_CURRENT_ASSIGNMENT_CHANGED';end if;
 customer:=a.customer_id;roots:=array[p_root];
 -- Include complete upstream credit source roots for incoming APPLY, including
 -- restores/historical target headers. UUID ordering is for normalization only.
 loop
  select array_agg(distinct id order by id)into sales from(
   select unnest(roots)id union select x.previous_sale_id from cp7_note.revisions x where x.root_sale_id=any(roots)
   union select x.replacement_sale_id from cp7_note.revisions x where x.root_sale_id=any(roots))s;
  select array_agg(distinct id order by id)into next_roots from(
   select unnest(roots)id union select rf.family_root_sale_id from cp7_credit.consumption_events ce
    join cp7_credit.cohorts ch on ch.id=ce.cohort_id join cp7_credit.return_families rf on rf.id=ch.family_id
    where ce.event_kind='APPLY'and ce.target_sale_id=any(sales))s;
  exit when next_roots is not distinct from roots;roots:=next_roots;
 end loop;
 foreach v_root in array roots loop
  select *into strict m from cp7_credit.current_leaf_assignment(v_root);
  if m.root_sale_id<>v_root or m.customer_id is distinct from customer then raise exception 'CP7_CREDIT_MEMBER_ROOT_MISMATCH';end if;
  v_leaf:=m.current_leaf_id;
  if exists(select 1 from erp.sales_headers h where(h.id=v_root or exists(select 1 from cp7_note.revisions x
   where x.root_sale_id=v_root and h.id in(x.previous_sale_id,x.replacement_sale_id)))
   and h.status in('POSTED','PARTIAL_PAID','PAID')and h.id<>v_leaf)then
   raise exception 'CP7_CREDIT_CURRENT_ASSIGNMENT_CHANGED';end if;
 end loop;
 if exists(select 1 from erp.sales_returns r where r.sale_id=any(sales)and r.status<>'DRAFT'
  and not exists(select 1 from cp7_credit.return_family_members mm where mm.return_id=r.id))then
  raise exception 'CP7_CREDIT_RETURN_REGISTRATION_INCOMPLETE';end if;
 if exists(select 1 from cp7_credit.return_family_members mm join erp.sales_returns r on r.id=mm.return_id
  join cp7_credit.return_families ff on ff.id=mm.family_id where r.sale_id=any(sales)and not ff.family_root_sale_id=any(roots))then
  raise exception 'CP7_CREDIT_MEMBER_ROOT_MISMATCH';end if;
 if exists(select 1 from(select family_ordinal,row_number()over(partition by family_root_sale_id order by family_ordinal)n
  from cp7_credit.return_families where family_root_sale_id=any(roots))x where x.family_ordinal<>x.n)then
  raise exception 'CP7_CREDIT_RETURN_REGISTRATION_INCOMPLETE';end if;
 for f in select *from cp7_credit.return_families where family_root_sale_id=any(roots)order by family_root_sale_id,family_ordinal loop
  if not exists(select 1 from cp7_credit.return_family_members mm where mm.family_id=f.id and mm.return_id=f.first_return_id
   and mm.member_kind='ORIGINAL')then raise exception 'CP7_CREDIT_RETURN_REGISTRATION_INCOMPLETE';end if;
  objects:=objects||jsonb_build_array(cp7_credit.materialized_fact('FAMILY',f.id,to_jsonb(f)));
  for m in select mm.*,r.sale_id,r.customer_id,r.status,r.physical_at from cp7_credit.return_family_members mm
   join erp.sales_returns r on r.id=mm.return_id where mm.family_id=f.id order by mm.return_id loop
   if not m.sale_id=any(sales)or m.customer_id is distinct from customer or m.status not in('POSTED','REVERSED')then
    raise exception 'CP7_CREDIT_MEMBER_ROOT_MISMATCH';end if;
   select *into strict a from cp7_credit.current_leaf_assignment(m.sale_id);
   if a.root_sale_id is distinct from f.family_root_sale_id then raise exception 'CP7_CREDIT_MEMBER_ROOT_MISMATCH';end if;
   if m.financial_state='JOURNAL'then
    if m.source_journal_id is null or not exists(select 1 from erp.journal_entries jj where jj.id=m.source_journal_id
     and jj.source_type='SALES_RETURN'and jj.source_id=m.return_id and jj.reversal_of_id is null
     and jj.economic_date=(m.physical_at at time zone'Asia/Jakarta')::date
     and jj.transaction_date>=jj.economic_date and jj.status=case when m.status='REVERSED'then'REVERSED'else'POSTED'end)
     or(select count(*)from erp.journal_entries jj where jj.source_type='SALES_RETURN'and jj.source_id=m.return_id
      and jj.reversal_of_id is null)<>1 then raise exception 'CP7_CREDIT_MEMBER_JOURNAL_MISMATCH';end if;
   elsif m.financial_state='NO_JOURNAL'then
    if m.source_journal_id is not null or exists(select 1 from erp.journal_entries jj where jj.source_type='SALES_RETURN'and jj.source_id=m.return_id)
     or not exists(select 1 from erp.sales_return_items ri where ri.return_id=m.return_id)
     or exists(select 1 from erp.sales_return_items ri where ri.return_id=m.return_id and(ri.qty_pcs<=0 or ri.refund_amount<>0 or ri.unit_hpp_snapshot<>0
      or not exists(select 1 from erp.sale_stock_allocations sa join erp.sales_items si on si.id=sa.sale_item_id
       where sa.id=ri.sale_stock_allocation_id and si.sale_id=m.sale_id and si.product_id=ri.product_id
        and sa.lot_id is not distinct from ri.lot_id and sa.qty_pcs>=ri.qty_pcs)
      or(select count(*)from erp.fg_stock_movements fm where fm.source_type='SALES_RETURN_ITEM'and fm.source_id=ri.id and fm.reversal_of_id is null)<>1
      or not exists(select 1 from erp.fg_stock_movements fm where fm.source_type='SALES_RETURN_ITEM'and fm.source_id=ri.id
       and fm.reversal_of_id is null and fm.movement_type='SALE_RETURN'and fm.product_id=ri.product_id
       and fm.lot_id is not distinct from ri.lot_id and fm.location_id=ri.location_id and fm.quality_grade=ri.quality_grade
       and fm.qty_signed=ri.qty_pcs and fm.unit_hpp_snapshot=0 and fm.customer_id=customer and fm.physical_at=m.physical_at)))then
     raise exception 'CP7_CREDIT_NO_JOURNAL_SOURCE_CHANGED';end if;
   else raise exception 'CP7_CREDIT_MEMBER_JOURNAL_MISMATCH';end if;
   objects:=objects||jsonb_build_array(cp7_credit.materialized_fact('MEMBER',m.return_id,
    (select to_jsonb(mm)from cp7_credit.return_family_members mm where mm.return_id=m.return_id)));
  end loop;
 end loop;
 select coalesce(array_agg(ch.id order by ch.id),'{}')into cohorts from cp7_credit.cohorts ch
  join cp7_credit.return_families ff on ff.id=ch.family_id where ff.family_root_sale_id=any(roots);
 for c in select ch.*,ff.family_root_sale_id from cp7_credit.cohorts ch join cp7_credit.return_families ff on ff.id=ch.family_id
  where ch.id=any(cohorts)order by ch.id loop
  if c.customer_id is distinct from customer or c.ar_account_id=c.credit_account_id or not exists(
   select 1 from cp7_credit.return_family_members mm join erp.sales_returns r on r.id=mm.return_id
   where mm.return_id=c.source_return_id and mm.family_id=c.family_id and r.sale_id=c.source_sale_id
    and(mm.financial_state,mm.source_journal_id,mm.financial_source_proof)is not distinct from
     (c.source_return_financial_state,c.source_return_journal_id,c.source_return_financial_proof))
   or not exists(select 1 from erp.journal_entries sj where sj.id=c.source_sale_journal_id and sj.source_type='SALE'
    and sj.source_id=c.source_sale_id and sj.reversal_of_id is null and sj.status in('POSTED','REVERSED'))then
   raise exception 'CP7_CREDIT_COHORT_SOURCE_MISMATCH';end if;
  objects:=objects||jsonb_build_array(cp7_credit.materialized_fact('COHORT',c.id,to_jsonb(c)-'family_root_sale_id'));
  if(select count(*)from cp7_credit.recognition_plans pp where pp.cohort_id=c.id and pp.plan_kind='INITIAL')<>1
   or not exists(select 1 from cp7_credit.recognition_plans pp where pp.id=c.initial_plan_id and pp.cohort_id=c.id
    and pp.plan_kind='INITIAL'and pp.net_amount=c.initial_net_amount and pp.expected_component_count>0)then
   raise exception 'CP7_CREDIT_PLAN_COHORT_MISMATCH';end if;
  for p in select *from cp7_credit.recognition_plans where cohort_id=c.id order by id loop
   if p.family_root_sale_id is distinct from c.family_root_sale_id or(p.plan_kind='INITIAL')<>(p.id=c.initial_plan_id)then
    raise exception 'CP7_CREDIT_PLAN_COHORT_MISMATCH';end if;
   select count(*),coalesce(sum(z.amount),0),coalesce(jsonb_agg(jsonb_build_object('amount',cp7_credit.cent_text(z.amount),
    'economic_date',z.economic_date::text,'transaction_date',z.transaction_date::text,
    'previous_economic_date',z.previous_economic_date::text,'previous_transaction_date',z.previous_transaction_date::text,
    'corners',z.corners)order by z.ordinal),'[]')into n,v_sum,components from cp7_credit.recognition_components z where z.plan_id=p.id;
   if n<>p.expected_component_count or cp7_credit.pg_jsonb_sha256(components)is distinct from p.components_sha256_pg
    or exists(select 1 from(select ordinal,row_number()over(order by ordinal)n from cp7_credit.recognition_components where plan_id=p.id)x where x.ordinal<>x.n)then
    raise exception 'CP7_CREDIT_COMPONENT_MANIFEST_CHANGED';end if;
   if v_sum is distinct from p.net_amount or p.has_recognition_effect is distinct from(n>0)then raise exception 'CP7_CREDIT_PLAN_TOTAL_CHANGED';end if;
   objects:=objects||jsonb_build_array(cp7_credit.materialized_fact('PLAN',p.id,to_jsonb(p)));
   select coalesce(jsonb_agg(jsonb_build_object('id',qq.id,'component_id',z.id,'ordinal',qq.ordinal,'amount',cp7_credit.cent_text(qq.amount))
    order by z.ordinal,qq.ordinal),'[]')into parts from cp7_credit.recognition_components z join cp7_credit.component_parts qq on qq.component_id=z.id where z.plan_id=p.id;
   if jsonb_array_length(parts)::bigint is distinct from p.expected_part_count or cp7_credit.pg_jsonb_sha256(parts)is distinct from p.parts_sha256_pg then
    raise exception 'CP7_CREDIT_PART_MANIFEST_CHANGED';end if;
   for cc in select *from cp7_credit.recognition_components where plan_id=p.id order by ordinal loop
    canonical:=components->(cc.ordinal-1);
    if cc.kernel_component is distinct from canonical or cc.component_sha256_pg is distinct from cp7_credit.pg_jsonb_sha256(canonical)
     or cc.amount is distinct from((cc.corners->>'d_here')::numeric-(cc.corners->>'d_prev_economic')::numeric
      -(cc.corners->>'d_prev_transaction')::numeric+(cc.corners->>'d_prev_both')::numeric)then
     raise exception 'CP7_CREDIT_COMPONENT_MANIFEST_CHANGED';end if;
    select count(*),sum(qq.amount)into n,v_sum from cp7_credit.component_parts qq where qq.component_id=cc.id;
    if n::numeric<>ceil(abs(cc.amount)/cp7_credit.native_journal_cent_max())or v_sum is distinct from cc.amount then
     raise exception 'CP7_CREDIT_PART_MANIFEST_CHANGED';end if;
    objects:=objects||jsonb_build_array(cp7_credit.materialized_fact('COMPONENT',cc.id,to_jsonb(cc)));
    for q in select *from cp7_credit.component_parts where component_id=cc.id order by ordinal loop
     if q.ordinal<1 or q.ordinal>n or q.amount is distinct from sign(cc.amount)*least(cp7_credit.native_journal_cent_max(),
      abs(cc.amount)-(q.ordinal-1)*cp7_credit.native_journal_cent_max())then raise exception 'CP7_CREDIT_PART_MANIFEST_CHANGED';end if;
     part_ids:=part_ids||q.id;
     select *into o from cp7_credit.component_journals where part_id=q.id;
     if o.part_id is null then raise exception 'CP7_CREDIT_PART_JOURNAL_INCOMPLETE';end if;
     select *into j from erp.journal_entries where id=o.journal_id;
     if j.id is null or(j.source_type,j.source_id,j.economic_date,j.transaction_date,j.reversal_of_id)is distinct from
      ('CP7_CUSTOMER_CREDIT_RECOGNITION',q.id,cc.economic_date,cc.transaction_date,null::uuid)
      or(o.economic_date,o.transaction_date)is distinct from(cc.economic_date,cc.transaction_date)
      or j.status not in('POSTED','REVERSED')then raise exception 'CP7_CREDIT_PART_JOURNAL_CHANGED';end if;
     if j.status='REVERSED'or exists(select 1 from erp.journal_entries jj where jj.reversal_of_id=j.id
      or(jj.source_type='JOURNAL_REVERSAL'and jj.source_id=j.id))then
      raise exception 'CP7_CREDIT_UNREPRESENTED_RECOGNITION_INVERSE';end if;
     expected_lines:=cp7_credit.native_cent_lines(jsonb_build_array(
      jsonb_build_object('account_id',c.ar_account_id,'customer_id',c.customer_id,'description','OW04 source-bound recognition',
       'debit',case when q.amount>0 then q.amount else 0 end,'credit',case when q.amount<0 then-q.amount else 0 end),
      jsonb_build_object('account_id',c.credit_account_id,'customer_id',c.customer_id,'description','OW04 source-bound recognition',
       'debit',case when q.amount<0 then-q.amount else 0 end,'credit',case when q.amount>0 then q.amount else 0 end)));
     select coalesce(jsonb_agg(jsonb_build_object('account_id',l.account_id,'customer_id',l.customer_id,'description',l.description,
      'debit',l.debit,'credit',l.credit)order by case when l.account_id=c.ar_account_id then 0 else 1 end,l.id),'[]')into actual_lines
      from erp.journal_lines l where l.journal_entry_id=j.id;
     if actual_lines is distinct from expected_lines or o.lines_sha256_pg is distinct from cp7_credit.native_lines_sha256(actual_lines)
      or exists(select 1 from erp.journal_lines l where l.journal_entry_id=j.id and
       (l.vendor_id is not null or l.contractor_id is not null or l.po_id is not null or l.product_id is not null))then
      raise exception 'CP7_CREDIT_PART_LINES_CHANGED';end if;
     journal_ids:=journal_ids||j.id;
     if c.family_root_sale_id=p_root then v_i:=v_i+q.amount;end if;
     objects:=objects||jsonb_build_array(cp7_credit.materialized_fact('PART',q.id,to_jsonb(q)),
      cp7_credit.materialized_fact('PART_JOURNAL',q.id,jsonb_build_object('link',to_jsonb(o),'actual',cp7_credit.materialized_journal_payload(j.id))));
    end loop;
   end loop;
  end loop;
 end loop;
 -- All signed consumers of upstream cohorts are included; restores are real
 -- linked facts, not a filter which drops the original consumption.
 for e in select *from cp7_credit.consumption_events where cohort_id=any(cohorts)order by id loop
  select *into strict c from cp7_credit.cohorts where id=e.cohort_id;
  if e.event_kind='APPLY'and not exists(select 1 from erp.sales_headers h where h.id=e.target_sale_id and h.customer_id=c.customer_id)then
   raise exception 'CP7_CREDIT_CONSUMPTION_TARGET_CHANGED';end if;
  select *into j from erp.journal_entries where id=e.journal_id;
  if j.id is null or(j.economic_date,j.transaction_date)is distinct from(e.economic_date,e.transaction_date)
   or j.status not in('POSTED','REVERSED')then raise exception 'CP7_CREDIT_CONSUMPTION_JOURNAL_CHANGED';end if;
  if e.amount<0 then
   select *into o from cp7_credit.consumption_events where id=e.restores_event_id;
   if o.id is null or o.amount<=0 or(e.cohort_id,e.event_kind,e.target_sale_id,e.cash_account_id,e.amount)is distinct from
    (o.cohort_id,o.event_kind,o.target_sale_id,o.cash_account_id,-o.amount)
    or e.economic_date<o.economic_date or e.transaction_date<o.transaction_date then
    raise exception 'CP7_CREDIT_CONSUMPTION_RESTORE_CHANGED';end if;
   if j.source_type='JOURNAL_REVERSAL'and(j.source_id is distinct from o.journal_id or j.reversal_of_id is distinct from o.journal_id
    or not exists(select 1 from erp.journal_entries oj where oj.id=o.journal_id and oj.status='REVERSED'))then
    raise exception 'CP7_CREDIT_CONSUMPTION_RESTORE_CHANGED';end if;
  end if;
  -- Posting source-ID protocol and full account/line/capacity proof are NOT
  -- invented here: the exact actual payload goes to the source-plan verifier.
  if exists(select 1 from erp.journal_lines l where l.journal_entry_id=j.id and(l.debit<0 or l.credit<0
   or l.debit::text in('NaN','Infinity','-Infinity')or l.credit::text in('NaN','Infinity','-Infinity')))
   or not exists(select 1 from erp.journal_lines l where l.journal_entry_id=j.id group by l.journal_entry_id
   having sum(l.debit)=sum(l.credit)and sum(l.debit)>0)then raise exception 'CP7_CREDIT_CONSUMPTION_JOURNAL_CHANGED';end if;
  journal_ids:=journal_ids||j.id;
  if e.event_kind='APPLY'and e.target_sale_id=p_sale then v_u:=v_u+e.amount;end if;
  objects:=objects||jsonb_build_array(cp7_credit.materialized_fact('CONSUMPTION',e.id,
   jsonb_build_object('event',to_jsonb(e),'actual',cp7_credit.materialized_journal_payload(j.id))));
 end loop;
 if exists(select 1 from erp.journal_entries jj where jj.source_type in('CP7_CUSTOMER_CREDIT_RECOGNITION','CP7_CUSTOMER_CREDIT_APPLY',
  'CP7_CUSTOMER_CREDIT_REFUND','CP7_CUSTOMER_CREDIT_EVENT_REVERSE')and
  ((jj.source_id=any(part_ids)and not jj.id=any(journal_ids))or
   (exists(select 1 from erp.journal_lines l where l.journal_entry_id=jj.id and l.customer_id=customer)
    and not exists(select 1 from cp7_credit.component_journals cj where cj.journal_id=jj.id)
    and not exists(select 1 from cp7_credit.consumption_events ce where ce.journal_id=jj.id))))then
   raise exception 'CP7_CREDIT_UNREGISTERED_FINANCIAL_JOURNAL';end if;
 select coalesce(jsonb_agg(x order by x->>'object_kind'collate"C",x->>'object_id'collate"C"),'[]')into objects from jsonb_array_elements(objects)x;
 state:=jsonb_build_object('contract_version','ow04.actual-materialized-objects.v1','sale_id',p_sale,'root_sale_id',p_root,'current_leaf_id',p_leaf,
  'upstream_root_ids',roots,'actual_objects',objects,'actual_objects_sha256',cp7_credit.pg_jsonb_sha256(objects),
  'I',cp7_credit.cent_text(v_i),'U',cp7_credit.cent_text(v_u),'adjustment',cp7_credit.cent_text(v_u-v_i),
  'source_authority_proven',false,'financial_marker_verified',false,'consumption_posting_contract_proven',false);
 return state;
end $function$

cp7_credit.enforce_initial_return_closur:
CREATE OR REPLACE FUNCTION cp7_credit.enforce_initial_return_closure_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare operation uuid;source_operation uuid;row jsonb:=to_jsonb(new);family uuid;plan uuid;
begin
 if tg_table_name in('consumption_events','financial_materializations','financial_materialization_objects')then
  select id into source_operation from cp7_credit.consumer_operations_v1 where id=
   (case when tg_table_name='financial_materialization_objects'then row->>'materialization_id'else row->>'id'end)::uuid;
  if source_operation is not null then perform cp7_credit.assert_consumer_closed_v1(source_operation);return null;end if;
 end if;
 operation:=cp7_credit.native_empty_closure_id_v1(tg_table_name,to_jsonb(new));
 if operation is not null then perform cp7_credit.assert_native_empty_closed_v1(operation);return null;end if;
 if tg_table_name in('financial_materializations','financial_materialization_objects')then
  select operation_id into source_operation from cp7_credit.source_operation_materializations_v1
   where financial_marker_id=(case when tg_table_name='financial_materializations'then row->>'id'else row->>'materialization_id'end)::uuid;
  if source_operation is not null then perform cp7_credit.assert_source_operation_closed_v1(source_operation);return null;end if;
 end if;
 if tg_table_name in('initial_return_materializations','initial_return_completions')then operation:=(row->>'operation_id')::uuid;
 elsif tg_table_name='initial_refund_operations'then select operation_id into operation from cp7_credit.initial_return_materializations where refund_operation_id=(row->>'id')::uuid;
 elsif tg_table_name='financial_materializations'then select operation_id into operation from cp7_credit.initial_return_materializations where materialization_id=(row->>'id')::uuid or refund_operation_id=(row->>'id')::uuid;
 elsif tg_table_name='financial_materialization_objects'then select operation_id into operation from cp7_credit.initial_return_materializations where materialization_id=(row->>'materialization_id')::uuid or refund_operation_id=(row->>'materialization_id')::uuid;
 else
  case tg_table_name
   when'return_families'then family:=(row->>'id')::uuid;
   when'return_family_members'then family:=(row->>'family_id')::uuid;
   when'cohorts'then family:=(row->>'family_id')::uuid;
   when'recognition_plans'then plan:=(row->>'id')::uuid;
   when'plan_support_events'then plan:=(row->>'plan_id')::uuid;
   when'recognition_components'then plan:=(row->>'plan_id')::uuid;
   when'component_parts'then select plan_id into plan from cp7_credit.recognition_components where id=(row->>'component_id')::uuid;
   when'component_journals'then select cc.plan_id into plan from cp7_credit.component_parts pp join cp7_credit.recognition_components cc on cc.id=pp.component_id where pp.id=(row->>'part_id')::uuid;
   when'consumption_events'then select family_id into family from cp7_credit.cohorts where id=(row->>'cohort_id')::uuid;
   when'plan_dependencies'then plan:=(row->>'plan_id')::uuid;
   else raise exception 'CP7_CREDIT_CLOSURE_TABLE_UNRECOGNIZED';
  end case;
  select operation_id into source_operation from cp7_credit.source_operation_plans_v1 where plan_id=plan;
  if source_operation is not null then perform cp7_credit.assert_source_operation_closed_v1(source_operation);return null;end if;
  select operation_id into operation from cp7_credit.initial_return_materializations where family_id=family or plan_id=plan;
 end if;
 if operation is null then raise exception 'CP7_CREDIT_UNOWNED_IMMUTABLE_FACT';end if;
 perform cp7_credit.assert_initial_return_closed_v1(operation);return null;
end $function$

cp7_credit.initial_base_events_v1(uuid,u:
CREATE OR REPLACE FUNCTION cp7_credit.initial_base_events_v1(p_sale uuid, p_exclude_return uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare ar uuid;answer jsonb;
begin
 if exists(select 1 from cp7_note.revisions where p_sale in(root_sale_id,previous_sale_id,replacement_sale_id))then
  raise exception 'CP7_CREDIT_NOTE_FAMILY_INITIAL_ADAPTER_UNIMPLEMENTED';end if;
 select account_id into strict ar from erp.accounting_account_mappings where mapping_key='AR_CUSTOMER';
 with recursive originals as(
  select j.id,j.id origin,'NET'::text kind from erp.journal_entries j
   where j.source_type='SALE'and j.source_id=p_sale and j.reversal_of_id is null
  union all select j.id,j.id,'NET'from erp.journal_entries j join erp.sales_returns r on r.id=j.source_id
   where j.source_type='SALES_RETURN'and r.sale_id=p_sale and r.id is distinct from p_exclude_return and j.reversal_of_id is null
  union all select j.id,j.id,'FUNDING'from erp.journal_entries j join erp.sales_payments p on p.id=j.source_id
   where j.source_type='SALES_PAYMENT'and p.sale_id=p_sale and j.reversal_of_id is null
  union all select j.id,j.id,'FUNDING'from erp.journal_entries j join erp.sales_payments p on p.id=j.source_id
   where j.source_type in('PAYMENT_CORRECTION_TIME_NEUTRAL','PAYMENT_CORRECTION_EFFECTIVE')and p.sale_id=p_sale and j.reversal_of_id is null
 ),walk(id,origin,kind)as(
  select *from originals union select child.id,w.origin,w.kind from walk w join erp.journal_entries child
   on(child.reversal_of_id=w.id or(child.source_type='JOURNAL_REVERSAL'and child.source_id=w.id))
 ),events as(
  select jsonb_build_object('id','journal:'||j.id::text,'kind',w.kind,
   'amount',cp7_credit.cent_text((case when w.kind='FUNDING'then -1 else 1 end)*coalesce(
     (select sum(l.debit-l.credit)from erp.journal_lines l where l.journal_entry_id=j.id and l.account_id=ar),0)),
   'economic_date',j.economic_date::text,'transaction_date',j.transaction_date::text,
   'source_sha256',ow04_source_proposal.sha(ow04_source_proposal.financial_journal_payload(j.id,ar)))v
  from walk w join erp.journal_entries j on j.id=w.id where j.status in('POSTED','REVERSED')
 )select coalesce(jsonb_agg(v order by v->>'id'collate"C"),'[]')into answer from events;
 answer:=answer||cp7_credit.consumer_incoming_funding_v1(p_sale);
 select coalesce(jsonb_agg(v order by v->>'id'collate"C"),'[]')into answer from jsonb_array_elements(answer)v;
 return answer;
end $function$

cp7_credit.initial_ordinal_input_v1(uuid:
CREATE OR REPLACE FUNCTION cp7_credit.initial_ordinal_input_v1(p_sale uuid, p_pending_plan uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare f cp7_credit.return_families;events jsonb;family_events jsonb;families jsonb:='[]';all_return_ids text[]:='{}';retained jsonb;consumers jsonb;
begin
 if p_pending_plan is not null and not exists(select 1 from cp7_credit.initial_return_work w join cp7_credit.execution_context e
  on(e.backend_pid,e.transaction_id,e.actor,e.request_id,e.plan_id)=(w.backend_pid,w.transaction_id,w.actor,w.request_id,w.plan_id)
  where w.backend_pid=pg_backend_pid()and w.transaction_id=txid_current()and w.plan_id=p_pending_plan and w.source_sale_id=p_sale
   and w.phase in('ENTERED','MATERIALIZED'))then raise exception 'CP7_CREDIT_EXACT_PENDING_PLAN_BASELINE_REQUIRED';end if;
 if exists(select 1 from erp.sales_returns r where r.sale_id=p_sale and r.status<>'DRAFT'
  and not exists(select 1 from cp7_credit.return_family_members m where m.return_id=r.id))then raise exception 'CP7_CREDIT_LEGACY_RETURN_ORDER_NOT_QUALIFIED';end if;
 events:=cp7_credit.initial_base_events_v1(p_sale);
 for f in select *from cp7_credit.return_families where family_root_sale_id=p_sale order by family_ordinal loop
  with recursive journals(id)as(
   select j.id from cp7_credit.return_family_members m join erp.journal_entries j on j.source_type='SALES_RETURN'and j.source_id=m.return_id
    where m.family_id=f.id and j.reversal_of_id is null
   union select j.id from journals p join erp.journal_entries j on j.reversal_of_id=p.id or(j.source_type='JOURNAL_REVERSAL'and j.source_id=p.id))
  select coalesce(jsonb_agg(x order by x->>'id'collate"C"),'[]')into family_events from jsonb_array_elements(events)x
   where substring(x->>'id'from 9)::uuid in(select id from journals);
  select all_return_ids||coalesce(array_agg(x->>'id'),'{}')into all_return_ids from jsonb_array_elements(family_events)x;
  select coalesce(jsonb_agg(jsonb_build_object('id','part:'||pp.id::text,'amount',cp7_credit.cent_text(pp.amount),'economic_date',cj.economic_date::text,
   'transaction_date',cj.transaction_date::text,'source_sha256',cp7_credit.pg_jsonb_sha256(jsonb_build_object('part',to_jsonb(pp),'journal_link',to_jsonb(cj))))order by pp.id),'[]')into retained
   from cp7_credit.cohorts ch join cp7_credit.recognition_plans rp on rp.cohort_id=ch.id join cp7_credit.recognition_components cc on cc.plan_id=rp.id
   join cp7_credit.component_parts pp on pp.component_id=cc.id join cp7_credit.component_journals cj on cj.part_id=pp.id
   where ch.family_id=f.id and rp.id is distinct from p_pending_plan;
  select coalesce(jsonb_agg(jsonb_build_object('id','consumption:'||ce.id::text,'amount',cp7_credit.cent_text(ce.amount),'economic_date',ce.economic_date::text,
   'transaction_date',ce.transaction_date::text,'source_sha256',ce.source_sha256)order by ce.id),'[]')into consumers
   from cp7_credit.consumption_events ce join cp7_credit.cohorts ch on ch.id=ce.cohort_id where ch.family_id=f.id;
  families:=families||jsonb_build_array(jsonb_build_object('family_id',f.id,'ordinal',f.family_ordinal::text,'first_return_id',f.first_return_id,
   'registration_sha256',f.source_sha256,'events',family_events,'retained_recognition',retained,'consumptions',consumers));
 end loop;
 select coalesce(jsonb_agg(x order by x->>'id'collate"C"),'[]')into events from jsonb_array_elements(events)x where not(x->>'id'=any(all_return_ids));
 return jsonb_build_object('contract_version','ow04.ordinal-input.v1','family_root_sale_id',p_sale,'base_events',events,'families',families);
end $function$

cp7_credit.native_source_enter(text,uuid:
CREATE OR REPLACE FUNCTION cp7_credit.native_source_enter(p_action text, p_source uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare sale uuid;a jsonb;families boolean;finished boolean:=false;
begin
 if cp7_credit.payment_native_enter_v1(p_action,p_source)then return;end if;
 if cp7_credit.native_empty_is_direct_v1()then perform cp7_credit.native_empty_source_enter_v1(p_action,p_source);return;end if;
 if p_action in('PAYMENT','PAYMENT_REVERSE')then select sale_id,status='REVERSED'and p_action='PAYMENT_REVERSE'into strict sale,finished from erp.sales_payments where id=p_source;
 elsif p_action='RETURN_REVERSE'then select sale_id,status='REVERSED'into strict sale,finished from erp.sales_returns where id=p_source;
 elsif p_action='SALE_REVERSE'then select id,status='REVERSED'into strict sale,finished from erp.sales_headers where id=p_source;
 else raise exception 'CP7_CREDIT_SOURCE_ACTION_UNIMPLEMENTED';end if;
 if cp7_credit.source_operation_owns_v1(p_action,p_source)then
  perform cp7_credit.source_operation_native_enter_v1(p_action,p_source);return;
 end if;
 if not cp7_credit.has_ow04_participation_v1(sale)then return;end if;
 -- Original Native require_internal/owner checks still surround this callback.
 a:=cp7_sales.command_access(p_action);
 select exists(select 1 from cp7_credit.return_families where family_root_sale_id=sale)
  or cp7_credit_remaining.payment_admitted_v1(p_action,p_source,sale)into families;
 if exists(select 1 from cp7_credit.cohorts ch join cp7_credit.return_families f on f.id=ch.family_id where f.family_root_sale_id=sale)
  or exists(select 1 from cp7_credit.consumption_events where event_kind='APPLY'and target_sale_id=sale)
   and not cp7_credit_remaining.payment_admitted_v1(p_action,p_source,sale)then
  raise exception 'CP7_CREDIT_REGISTERED_SOURCE_MUTATION_REQUIRES_BOUND_RECONCILIATION'using detail=cp7_credit_followups.source_mutation_reasons_v1(p_action,sale);end if;
 if finished then return;end if; -- Native early replay has no completion hook.
 insert into cp7_credit.source_mutation_scope values(pg_backend_pid(),txid_current(),auth.uid(),p_action,p_source,sale,a,families);
 if families then perform cp7_credit.assert_simple_native_base_v1(sale);perform cp7_credit.assert_zero_excess_v1(cp7_credit.initial_base_events_v1(sale));end if;
 if cp7_sales.command_access(p_action)is distinct from a then raise exception using errcode='42501',message='CP7_CREDIT_SOURCE_ACCESS_CHANGED';end if;
end $function$

cp7_note.command(jsonb,uuid,text):
CREATE OR REPLACE FUNCTION cp7_note.command(p_payload jsonb, p_request uuid, p_expected text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb;old cp7_note.requests%rowtype;h erp.sales_headers%rowtype;root uuid;leaf uuid;
 revision bigint;replaced uuid;native_request uuid;result jsonb;draft jsonb;line jsonb;payment record;returned record;
 paid jsonb;returns jsonb;returned_lines jsonb;new_payment uuid;new_return uuid;new_return_item uuid;allocation uuid;
 return_lineage jsonb:='{}'::jsonb;
 correction_id uuid:=gen_random_uuid();before_movements uuid[];origin record;new_move record;anchor uuid;
begin
 if current_setting('transaction_isolation')<>'read committed'then raise exception 'CP7_FRESH_ACCESS_REQUIRED';end if;
 a:=cp7_note.access_now();perform cp7_sales.validate_draft(p_payload-'item_lineage',true);
 if p_request is null or p_expected is null or p_expected!~'^[1-9][0-9]{0,18}$'then raise exception 'CP7_NOTE_REQUEST_REQUIRED';end if;
 insert into cp7_note.requests values(auth.uid(),p_request,p_payload,p_expected,null)on conflict do nothing;
 select *into strict old from cp7_note.requests where actor=auth.uid()and request_id=p_request for update;
 if old.payload is distinct from p_payload or old.expected_version is distinct from p_expected then raise exception 'CP7_NOTE_REQUEST_CHANGED';end if;
 if cp7_note.access_now()is distinct from a then raise exception using errcode='42501',message='CP7_NOTE_ACCESS_CHANGED';end if;
 if old.response is not null then return old.response;end if;
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 perform pg_advisory_xact_lock(hashtextextended('FGBOOK|GLOBAL',0));
 if cp7_note.access_now()is distinct from a then raise exception using errcode='42501',message='CP7_NOTE_ACCESS_CHANGED';end if;
 leaf:=(p_payload->>'sale_id')::uuid;
 perform 1 from erp.sales_payments where sale_id=leaf order by id for update;
 perform 1 from erp.sales_returns where sale_id=leaf order by id for update;
 select *into h from erp.sales_headers where id=leaf for update;
 if h.id is null or h.status not in('POSTED','PARTIAL_PAID','PAID')then raise exception 'CP7_NOTE_ACTIVE_POSTED_ONLY';end if;
 if h.row_version::text<>p_expected or cp7_sales.review_token(h.id)<>p_payload->>'review_token'then raise exception 'CP7_NOTE_REVIEW_CHANGED';end if;
 -- Historical correction keeps the actual original event identity/time.
 if p_payload->>'sale_number'is distinct from h.sale_number
  or(p_payload->>'sale_date')::timestamptz is distinct from h.sale_date
  or(p_payload->>'customer_id')::uuid is distinct from h.customer_id
  or(p_payload->>'source_location_id')::uuid is distinct from h.source_location_id then raise exception 'CP7_NOTE_SOURCE_IDENTITY_CHANGED';end if;
 select root_sale_id into root from cp7_note.revisions where replacement_sale_id=leaf;
 root:=coalesce(root,leaf);
 select coalesce(max(r.revision),0)+1 into revision from cp7_note.revisions r where r.root_sale_id=root;
 if exists(select 1 from cp7_note.revisions where previous_sale_id=leaf)then raise exception 'CP7_NOTE_SOURCE_SUPERSEDED';end if;
 if exists(select 1 from erp.sales_payments where sale_id=leaf and status='DRAFT')
  or exists(select 1 from erp.sales_returns where sale_id=leaf and status='DRAFT')then
  raise exception 'CP7_NOTE_PENDING_CHILD_REVIEW_REQUIRED';end if;
 -- A native cash reallocation is journaled at its predecessor's reversal date.
 -- Replaying it here would move that cash back to the original receipt clock;
 -- like payment correction, such a payment stays outside this command.
 if exists(select 1 from erp.sales_payments where sale_id=leaf and status='POSTED'and replaces_payment_id is not null)then
  raise exception 'CP7_NOTE_REALLOCATED_PAYMENT_REVIEW_REQUIRED';end if;
 select coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object('advance_id',l.advance_id)order by p.payment_date,p.id),'[]')into paid
 from erp.sales_payments p left join erp.initial_import_prepayment_payments l on l.payment_id=p.id
 where p.sale_id=leaf and p.status='POSTED';
 select coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('items',
  (select jsonb_agg(to_jsonb(i)||jsonb_build_object('allocation_location_id',x.location_id)order by i.id)
    from erp.sales_return_items i join erp.sale_stock_allocations x on x.id=i.sale_stock_allocation_id where i.return_id=r.id))order by r.physical_at,r.id),'[]')into returns
 from erp.sales_returns r where r.sale_id=leaf and r.status='POSTED';
 select array_agg(m.id)into before_movements from erp.fg_stock_movements m where
  (m.source_type='SALE_ITEM'and exists(select 1 from erp.sales_items i where i.id=m.source_id and i.sale_id=leaf)
   or m.source_type='SALES_RETURN_ITEM'and exists(select 1 from erp.sales_return_items i join erp.sales_returns r on r.id=i.return_id where i.id=m.source_id and r.sale_id=leaf and r.status='POSTED'))
  and m.movement_type in('SALE','SALE_RETURN')and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id);
 insert into cp7_note.context values(pg_backend_pid(),txid_current(),auth.uid(),leaf);
 insert into cp7_sales.command_context values(pg_backend_pid(),txid_current(),auth.uid(),leaf,'SALE_REVERSE');
 perform set_config('app.change_reason',p_payload->>'change_reason',true);
 -- D15-1 / Sol SOL-R1-001: the cash guard judges the end state of inverse + replacement, not the half-way balance.
 if pg_catalog.to_regprocedure('cp7_guard.begin_compound(text)')is not null then perform cp7_guard.begin_compound('SALES_NOTE_CORRECTION');end if;
 -- Remove active children before reversing the invoice, then restore their
 -- immutable original physical inputs onto its replacement in one command.
 for payment in select *from jsonb_to_recordset(paid)as p(id uuid)loop
  perform cp7_sales.command_access('PAYMENT_REVERSE');perform cp7_note.reverse_sales_payment(payment.id,p_payload->>'change_reason');
 end loop;
 for returned in select *from jsonb_to_recordset(returns)as r(id uuid)loop
  perform cp7_sales.command_access('RETURN_REVERSE');perform cp7_note.reverse_sales_return(returned.id,p_payload->>'change_reason');
 end loop;
 perform cp7_note.reverse_sale(leaf,p_payload->>'change_reason');
 native_request:=md5(auth.uid()::text||':NOTE:'||p_request::text)::uuid;
 draft:=(p_payload-'sale_id'-'review_token'-'change_reason'-'item_lineage')||jsonb_build_object('sale_number',left((select sale_number from erp.sales_headers where id=root),38)||' · R'||revision::text||'-'||left(p_request::text,8),'reason',p_payload->>'change_reason');
 result:=erp.save_sale_draft_v2(draft,native_request,null);
 replaced:=(result->>'sale_id')::uuid;
 perform cp7_note.bind_items(leaf,replaced,correction_id,p_payload->'items',p_payload->'item_lineage');
 perform erp.post_sale(replaced);
 for returned in select value from jsonb_array_elements(returns)loop
  perform cp7_sales.command_access('RETURN');
  insert into erp.sales_returns(return_number,sale_id,customer_id,physical_at,notes,status,created_by)
  values(left(returned.value->>'return_number',38)||' · K-'||left(p_request::text,8),replaced,h.customer_id,
   (returned.value->>'physical_at')::timestamptz,returned.value->>'notes','DRAFT',erp.current_app_user_id())returning id into new_return;
  for line in select value from jsonb_array_elements(returned.value->'items')loop
   select x.id into allocation from erp.sale_stock_allocations x join erp.sales_items i on i.id=x.sale_item_id
    where i.sale_id=replaced and i.product_id=(line->>'product_id')::uuid and x.lot_id=(line->>'lot_id')::uuid
     and x.location_id=(line->>'allocation_location_id')::uuid
     and x.sale_item_id=(select l.replacement_item_id from cp7_note.item_lineage l
      join erp.sale_stock_allocations prior_allocation on prior_allocation.sale_item_id=l.previous_item_id
      where prior_allocation.id=(line->>'sale_stock_allocation_id')::uuid and l.replacement_item_id=x.sale_item_id)
     and not exists(select 1 from erp.sales_return_items z where z.return_id=new_return and z.sale_stock_allocation_id=x.id)
     and x.qty_pcs>=
      (line->>'qty_pcs')::integer+coalesce((select sum(z.qty_pcs)from erp.sales_return_items z where z.sale_stock_allocation_id=x.id),0)
    order by x.id limit 1;
   if allocation is null then raise exception 'CP7_NOTE_RETURN_ALLOCATION_CHANGED';end if;
   -- The refund was agreed for the old net price of each returned piece.
   -- Replaying it onto a line sold at another net price would overstate (or
   -- refuse) receivable without anyone seeing it: correct the return first.
   if exists(select 1 from erp.sale_stock_allocations old_x join erp.sales_items o on o.id=old_x.sale_item_id,
     erp.sale_stock_allocations new_x join erp.sales_items n on n.id=new_x.sale_item_id
    where old_x.id=(line->>'sale_stock_allocation_id')::uuid and new_x.id=allocation
     and(o.qty_pcs*o.unit_price_snapshot-coalesce(o.discount_amount,0))*n.qty_pcs
      <>(n.qty_pcs*n.unit_price_snapshot-coalesce(n.discount_amount,0))*o.qty_pcs)then
    raise exception 'CP7_NOTE_RETURNED_LINE_PRICE_CHANGED';end if;
   insert into erp.sales_return_items(return_id,sale_stock_allocation_id,product_id,lot_id,location_id,qty_pcs,quality_grade,refund_amount,notes)
   values(new_return,allocation,(line->>'product_id')::uuid,(line->>'lot_id')::uuid,(line->>'location_id')::uuid,
    (line->>'qty_pcs')::integer,line->>'quality_grade',(line->>'refund_amount')::numeric,line->>'notes')returning id into new_return_item;
   return_lineage:=return_lineage||jsonb_build_object(new_return_item::text,line->>'id');
  end loop;
  perform erp.post_sales_return(new_return);
 end loop;
 for payment in select value from jsonb_array_elements(paid)loop
  perform cp7_sales.command_access('PAYMENT');
  insert into erp.sales_payments(sale_id,payment_number,payment_date,amount,cash_account_id,payment_method,reference_number,notes,status,created_by)
  values(replaced,left(payment.value->>'payment_number',38)||' · K-'||left(p_request::text,8),
   (payment.value->>'payment_date')::timestamptz,(payment.value->>'amount')::numeric,(payment.value->>'cash_account_id')::uuid,
   payment.value->>'payment_method',payment.value->>'reference_number',payment.value->>'notes','DRAFT',erp.current_app_user_id())returning id into new_payment;
  if payment.value->>'advance_id'is not null then
   -- Same original wallet and amount. Accepted Native funding validation locks
   -- it, checks its actual remaining amount/customer/source snapshot and dates,
   -- and posts liability/AR rather than cash. No opening balance is edited.
   insert into erp.initial_import_prepayment_payments(payment_id,advance_id,sales_payment_id,payment_snapshot)
   select new_payment,(payment.value->>'advance_id')::uuid,new_payment,to_jsonb(p)-'status'
   from erp.sales_payments p where p.id=new_payment;
  end if;
  perform erp.post_sales_payment(new_payment);
  insert into cp7_note.payment_replays(previous_payment_id,replacement_payment_id,correction_id)
  values((payment.value->>'id')::uuid,new_payment,correction_id);
 end loop;
 if pg_catalog.to_regprocedure('cp7_guard.end_compound()')is not null then perform cp7_guard.end_compound();end if;
 -- Collapse compensating movements under their original source card. A newly
 -- added SKU gets its own Native card inserted beside this note's source,
 -- using the accepted move writer. Unrelated manual order is never reset.
 -- Original quantity, recorded clock and posted price are never edited.
 for new_move in select m.*from erp.fg_stock_movements m where m.reversal_of_id=any(coalesce(before_movements,'{}'::uuid[]))
  or m.source_type='SALE_ITEM'and exists(select 1 from erp.sales_items i where i.id=m.source_id and i.sale_id=replaced)
  or exists(select 1 from erp.fg_stock_movements reservation join erp.sales_items i on i.id=reservation.source_id
    where reservation.id=m.reversal_of_id and reservation.source_type='SALE_ITEM'and i.sale_id=replaced)
  or m.source_type='SALES_RETURN_ITEM'and exists(select 1 from erp.sales_return_items i join erp.sales_returns r on r.id=i.return_id where i.id=m.source_id and r.sale_id=replaced)
  order by case when m.movement_type='SALE'and m.reversal_of_id is null then 0
    when m.reversal_of_id is null then 1 else 2 end,m.system_created_at,m.id loop
  anchor:=null;
  if new_move.reversal_of_id is not null then
   select coalesce(l.origin_id,new_move.reversal_of_id)into anchor from(select 1)x left join cp7_fg.correction_movements l on l.member_id=new_move.reversal_of_id;
  elsif new_move.source_type='SALE_ITEM'and exists(select 1 from erp.sales_items where id=new_move.source_id and sale_id=replaced)then
   anchor:=cp7_note.line_origin(leaf,new_move.source_id,new_move.product_id,new_move.lot_id,new_move.location_id,new_move.quality_grade);
   if anchor is null then
    select coalesce(l.origin_id,m.id)into anchor from erp.fg_stock_movements m join erp.sales_items i on i.id=m.source_id
     left join cp7_fg.correction_movements l on l.member_id=m.id
     where i.sale_id=replaced and i.id=new_move.source_id and m.movement_type='SALE'and m.product_id=new_move.product_id
      and m.location_id=new_move.location_id and m.quality_grade=new_move.quality_grade
     order by(m.lot_id=new_move.lot_id)desc,m.book_order,m.id limit 1;
    if anchor=new_move.id then
     select coalesce(l.origin_id,m.id) as origin_id into origin from erp.fg_stock_movements m join erp.sales_items i on i.id=m.source_id
      left join cp7_fg.correction_movements l on l.member_id=m.id
      where i.sale_id=leaf and m.movement_type='SALE'order by m.book_order,m.id limit 1;
     if origin.origin_id is null then raise exception 'CP7_NOTE_ORIGINAL_BOOK_SOURCE_REQUIRED';end if;
     perform erp.move_fg_stock_card_row_to_position(new_move.id,cp7_fg.book_anchor(new_move.id,origin.origin_id,'AFTER'));
    end if;
   end if;
  elsif new_move.source_type='SALES_RETURN_ITEM'then
   select coalesce(l.origin_id,m.id)into anchor from erp.fg_stock_movements m join erp.sales_return_items i on i.id=m.source_id join erp.sales_returns r on r.id=i.return_id
    left join cp7_fg.correction_movements l on l.member_id=m.id where r.sale_id=leaf and i.id=(return_lineage->>new_move.source_id::text)::uuid and m.movement_type='SALE_RETURN'
     and m.product_id=new_move.product_id and m.lot_id is not distinct from new_move.lot_id and m.location_id=new_move.location_id
     and m.quality_grade=new_move.quality_grade and m.physical_at=new_move.physical_at order by m.book_order,m.id limit 1;
  end if;
  if anchor is not null and anchor<>new_move.id then insert into cp7_fg.correction_movements values(new_move.id,anchor,correction_id,clock_timestamp());end if;
 end loop;
 if cp7_note.access_now()is distinct from a then raise exception using errcode='42501',message='CP7_NOTE_ACCESS_CHANGED';end if;
 insert into cp7_note.revisions(id,root_sale_id,previous_sale_id,replacement_sale_id,revision,actor,request_id,reason,effective_at)
 values(correction_id,root,leaf,replaced,revision,auth.uid(),p_request,p_payload->>'change_reason',h.sale_date);
 delete from cp7_sales.command_context where backend_pid=pg_backend_pid()and transaction_id=txid_current();
 delete from cp7_note.context where backend_pid=pg_backend_pid()and transaction_id=txid_current();
 result:=jsonb_build_object('contract_version','cp7.note-correction-outcome.v1','kind','COMMITTED_OUTCOME',
  'action','CORRECT','request_id',p_request,'root_sale_id',root,'previous_sale_id',leaf,
  'sale_id',replaced,'revision_id',correction_id,'revision',revision::text,'effective_at',h.sale_date);
 update cp7_note.requests set response=result where actor=auth.uid()and request_id=p_request;
 return result;
end $function$

cp7_note.reverse_sale(uuid,text):
CREATE OR REPLACE FUNCTION cp7_note.reverse_sale(p_sale_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.sales_headers%rowtype;
  r record;
  v_journal uuid;
  v_expected numeric(24,6);
  v_po uuid;
begin
 perform cp7_note.require_context();
  perform erp.require_owner_admin();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  perform erp.require_owner_admin();
  perform cp7_credit.native_source_enter('SALE_REVERSE',p_sale_id);
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal penjualan wajib diisi'; end if;

  select * into h from erp.sales_headers where id=p_sale_id for update;
  if h.id is null then raise exception 'Penjualan tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status not in('POSTED','PARTIAL_PAID','PAID') then
    raise exception 'Hanya penjualan yang sudah POSTED/aktif yang dapat direverse';
  end if;
  if exists(select 1 from erp.sales_payments where sale_id=h.id and status='POSTED') then
    raise exception 'Penjualan ini sudah memiliki pembayaran customer. Reverse pembayaran aktif terlebih dahulu.';
  end if;
  if exists(select 1 from erp.sales_returns where sale_id=h.id and status='POSTED') then
    raise exception 'Penjualan ini sudah memiliki retur POSTED. Reverse retur aktif terlebih dahulu.';
  end if;

  -- A missing PO HPP journal is corruption. A sub-cent allocation whose
  -- cumulative PO target did not move is legitimately journal-free.
  for v_po in
    select distinct fl.po_id
    from erp.sale_stock_allocations a
    join erp.sales_items i on i.id=a.sale_item_id
    join erp.fg_lots fl on fl.id=a.lot_id
    where i.sale_id=h.id and fl.po_id is not null order by fl.po_id
  loop
    perform erp.assert_po_hpp_target_book_v2620e(v_po);
  end loop;

  for r in
    select distinct fl.product_id
    from erp.sale_stock_allocations a
    join erp.sales_items i on i.id=a.sale_item_id
    join erp.fg_lots fl on fl.id=a.lot_id
    where i.sale_id=h.id and fl.po_id is null
    order by fl.product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  -- HPP may legitimately have had zero document delta.  Global target/book
  -- proof above detects missing value; only commercial value requires a SALE journal.
  select round(coalesce((select sum(line_total)
           from erp.sales_items where sale_id=h.id),0),2)
  into v_expected;
  select id into v_journal from erp.journal_entries
  where source_type='SALE' and source_id=h.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if v_expected>0.005 and v_journal is null then
    raise exception 'Jurnal penjualan tidak ditemukan; reversal dibatalkan agar piutang/HPP tidak rusak';
  end if;

  for r in
    select fm.id
    from erp.fg_stock_movements fm
    join erp.sales_items i on i.id=fm.source_id
    where i.sale_id=h.id and fm.source_type='SALE_ITEM' and fm.movement_type='SALE'
      and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=fm.id)
    order by fm.physical_at desc,fm.id desc
  loop
    perform cp7_note.reverse_fg_movement(r.id,p_reason);
  end loop;

  if v_journal is not null then perform cp7_note.reverse_journal(v_journal,p_reason); end if;
  update erp.sales_headers set status='REVERSED' where id=h.id;

  for r in
    select distinct fl.product_id
    from erp.sale_stock_allocations a
    join erp.sales_items i on i.id=a.sale_item_id
    join erp.fg_lots fl on fl.id=a.lot_id
    where i.sale_id=h.id and fl.po_id is null
    order by fl.product_id
  loop
    perform erp.sync_non_po_product_hpp_to_gl_v2620f(
      r.product_id,((h.sale_date AT TIME ZONE 'Asia/Jakarta'::text))::date,'SALE_REVERSAL',h.id,
      'Reverse Sale '||h.id::text||': '||p_reason
    );
  end loop;

  for v_po in
    select distinct fl.po_id
    from erp.sale_stock_allocations a
    join erp.sales_items i on i.id=a.sale_item_id
    join erp.fg_lots fl on fl.id=a.lot_id
    where i.sale_id=h.id and fl.po_id is not null order by fl.po_id
  loop
    -- First reflect only the exact compensating journal, then let the normal
    -- synchronizer post any cumulative-rounding redistribution still needed by
    -- the remaining active sales.
    perform erp.refresh_po_hpp_gl_baseline(v_po);
    perform erp.sync_po_hpp_to_gl(v_po,((h.sale_date AT TIME ZONE 'Asia/Jakarta'::text))::date);
    perform erp.refresh_po_hpp_gl_baseline(v_po);
    perform erp.assert_po_hpp_target_book_v2620e(v_po);
  end loop;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('sales_headers',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
  perform cp7_credit.native_source_complete('SALE_REVERSE',p_sale_id);
  perform erp.require_owner_admin();
end
$function$

cp7_sales_return_correction.command(json:
CREATE OR REPLACE FUNCTION cp7_sales_return_correction.command(p jsonb, p_request uuid, p_expected text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare a jsonb;old cp7_sales_return_correction.requests;h erp.sales_headers;r erp.sales_returns;
 replacement uuid;line jsonb;allocation record;origin uuid;movement record;
 link cp7_sales_return_correction.links;result jsonb;resolved jsonb;correction_id uuid:=gen_random_uuid();
begin
 if current_setting('transaction_isolation')<>'read committed'then raise exception 'CP7_FRESH_ACCESS_REQUIRED';end if;
 a:=cp7_sales_return_correction.access_now();perform cp7_sales_return_correction.validate(p);
 if p_request is null or p_expected is null or p_expected!~'^[1-9][0-9]{0,18}$'then raise exception 'CP7_RETURN_CORRECTION_REQUEST_REQUIRED';end if;
 insert into cp7_sales_return_correction.requests values(auth.uid(),p_request,p,p_expected,null)on conflict do nothing;
 select *into strict old from cp7_sales_return_correction.requests where actor=auth.uid()and request_id=p_request for update;
 if old.payload is distinct from p or old.expected_version is distinct from p_expected then raise exception 'CP7_RETURN_CORRECTION_REQUEST_CHANGED';end if;
 if cp7_sales_return_correction.access_now()is distinct from a then raise exception using errcode='42501',message='CP7_SALES_ACCESS_CHANGED';end if;
 if old.response is not null then return old.response;end if;
 if exists(select 1 from cp7_sales.command_context where backend_pid=pg_backend_pid()and transaction_id=txid_current())then
  raise exception using errcode='42501',message='CP7_RETURN_CORRECTION_PRIVATE_CONTEXT_REQUIRED';end if;
 -- Preserve Native FG, child, header and allocation lock order.
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 perform 1 from erp.sales_payments where sale_id=(p->>'sale_id')::uuid order by id for update;
 perform 1 from erp.sales_returns where sale_id=(p->>'sale_id')::uuid order by id for update;
 select *into h from erp.sales_headers where id=(p->>'sale_id')::uuid for update;
 select *into r from erp.sales_returns where id=(p->>'return_id')::uuid and sale_id=h.id;
 if h.id is null or r.id is null then raise exception 'CP7_RETURN_CORRECTION_NOT_FOUND';end if;
 perform 1 from erp.sales_items where sale_id=h.id order by id for update;
 perform 1 from erp.sale_stock_allocations x where exists(select 1 from erp.sales_items i
  where i.id=x.sale_item_id and i.sale_id=h.id)order by x.id for update;
 perform 1 from erp.sales_return_items i join erp.sales_returns rh on rh.id=i.return_id
  where rh.sale_id=h.id order by i.id for update of i;
 perform 1 from erp.locations where id in(select (value->>'location_id')::uuid from jsonb_array_elements(p->'replacement'->'items'))order by id for share;
 perform 1 from erp.hpp_versions v where v.is_current and exists(select 1 from erp.sale_stock_allocations x
  join erp.sales_items i on i.id=x.sale_item_id where i.sale_id=h.id and x.lot_id=v.lot_id)order by v.id for share;
 if cp7_sales_return_correction.access_now()is distinct from a then raise exception using errcode='42501',message='CP7_SALES_ACCESS_CHANGED';end if;
 if h.row_version::text is distinct from p_expected or cp7_sales.review_token(h.id)is distinct from p->>'review_token'
  or cp7_sales_return_correction.review_token(r.id)is distinct from p->>'return_review_token'then raise exception 'CP7_RETURN_CORRECTION_STALE_REVIEW';end if;
 if r.status<>'POSTED'or h.status not in('POSTED','PARTIAL_PAID','PAID')
  or exists(select 1 from cp7_sales_return_correction.links where original_id=r.id)then raise exception 'CP7_RETURN_CORRECTION_INELIGIBLE';end if;
 if(p->'replacement'->>'physical_at')::timestamptz>statement_timestamp()then raise exception 'CP7_SALES_RETURN_FUTURE_DATE';end if;
 if r.physical_at=(p->'replacement'->>'physical_at')::timestamptz and r.notes is not distinct from p->'replacement'->>'notes'
  and(select jsonb_agg(jsonb_build_object('allocation_id',i.sale_stock_allocation_id,'location_id',i.location_id,
   'qty_pcs',i.qty_pcs::text,'quality_grade',i.quality_grade,'refund_amount',round(i.refund_amount,2)::text,'notes',i.notes)order by i.sale_stock_allocation_id)
   from erp.sales_return_items i where i.return_id=r.id)=(select jsonb_agg(jsonb_build_object(
    'allocation_id',(value->>'allocation_id')::uuid,'location_id',(value->>'location_id')::uuid,
    'qty_pcs',value->>'qty_pcs','quality_grade',value->>'quality_grade','refund_amount',round((value->>'refund_amount')::numeric,2)::text,
    'notes',value->>'notes')order by value->>'allocation_id')from jsonb_array_elements(p->'replacement'->'items'))then
  raise exception 'CP7_RETURN_CORRECTION_UNCHANGED';end if;
 perform set_config('app.change_reason',btrim(p->>'change_reason'),true);
 insert into cp7_sales_return_correction.context values(pg_backend_pid(),txid_current(),auth.uid(),p_request,h.id,r.id);
 insert into cp7_sales.command_context values(pg_backend_pid(),txid_current(),auth.uid(),h.id,'RETURN_REVERSE');
 perform cp7_sales_return_correction.reverse_sales_return(r.id,btrim(p->>'change_reason'));
 -- Exact inverses share the effective original card. No Native row is edited.
 for movement in select m.id,m.reversal_of_id from erp.fg_stock_movements m
  join erp.fg_stock_movements o on o.id=m.reversal_of_id
  join erp.sales_return_items i on i.id=o.source_id and o.source_type='SALES_RETURN_ITEM'
  where i.return_id=r.id and not exists(select 1 from cp7_fg.correction_movements x where x.member_id=m.id)loop
  select coalesce(x.origin_id,movement.reversal_of_id)into origin from(select 1)t
   left join cp7_fg.correction_movements x on x.member_id=movement.reversal_of_id;
  insert into cp7_fg.correction_movements values(movement.id,origin,correction_id,clock_timestamp());
 end loop;
 delete from cp7_sales.command_context where backend_pid=pg_backend_pid()and transaction_id=txid_current();
 delete from cp7_sales_return_correction.context where backend_pid=pg_backend_pid()and transaction_id=txid_current();
 insert into cp7_sales.command_context values(pg_backend_pid(),txid_current(),auth.uid(),h.id,'RETURN');
 insert into erp.sales_returns(return_number,sale_id,customer_id,physical_at,notes,status,created_by)
 values('K-'||p_request::text,h.id,h.customer_id,(p->'replacement'->>'physical_at')::timestamptz,
  p->'replacement'->>'notes','DRAFT',erp.current_app_user_id())returning id into replacement;
 for line in select value from jsonb_array_elements(p->'replacement'->'items')loop
  select x.id,x.lot_id,i.product_id into allocation from erp.sale_stock_allocations x join erp.sales_items i on i.id=x.sale_item_id
   where x.id=(line->>'allocation_id')::uuid and i.sale_id=h.id;
  if not found then raise exception 'CP7_SALES_RETURN_ALLOCATION_CHANGED';end if;
  insert into erp.sales_return_items(return_id,sale_stock_allocation_id,product_id,lot_id,location_id,qty_pcs,quality_grade,refund_amount,notes)
  values(replacement,allocation.id,allocation.product_id,allocation.lot_id,(line->>'location_id')::uuid,
   (line->>'qty_pcs')::integer,line->>'quality_grade',(line->>'refund_amount')::numeric,line->>'notes');
 end loop;
 perform erp.post_sales_return(replacement);
 -- A changed date/destination/grade remains a separate physical row. Only an
 -- identical product/lot/destination/grade/time can share an original card.
 for movement in select m.*from erp.fg_stock_movements m join erp.sales_return_items i
  on i.id=m.source_id and m.source_type='SALES_RETURN_ITEM'where i.return_id=replacement and m.movement_type='SALE_RETURN'loop
  select coalesce(x.origin_id,o.id)into origin from erp.fg_stock_movements o
   join erp.sales_return_items i on i.id=o.source_id and o.source_type='SALES_RETURN_ITEM'
   left join cp7_fg.correction_movements x on x.member_id=o.id
   where i.return_id=r.id and i.sale_stock_allocation_id=(select sale_stock_allocation_id from erp.sales_return_items where id=movement.source_id)
    and o.movement_type='SALE_RETURN'and o.product_id=movement.product_id and o.lot_id is not distinct from movement.lot_id
    and o.location_id=movement.location_id and o.quality_grade=movement.quality_grade and o.physical_at=movement.physical_at
   order by o.book_order,o.id limit 1;
  if origin is not null then insert into cp7_fg.correction_movements values(movement.id,origin,correction_id,clock_timestamp());end if;
 end loop;
 if cp7_sales_return_correction.access_now()is distinct from a then raise exception using errcode='42501',message='CP7_SALES_ACCESS_CHANGED';end if;
 insert into cp7_sales_return_correction.links(id,original_id,replacement_id,sale_id,actor,request_id,reason)
 values(correction_id,r.id,replacement,h.id,auth.uid(),p_request,btrim(p->>'change_reason'))returning *into link;
 delete from cp7_sales.command_context where backend_pid=pg_backend_pid()and transaction_id=txid_current();
 select *into strict h from erp.sales_headers where id=h.id;
 resolved:=public.erp_cp7_resolve_transaction_source_v1(jsonb_build_object('source_type','SALES_RETURN','source_id',replacement));
 if resolved->>'status'is distinct from 'AVAILABLE'or resolved#>>'{document,domain}'is distinct from 'SALE'
  or resolved#>>'{document,id}'is distinct from h.id::text
  or resolved#>>'{document,focus,kind}'is distinct from 'SALES_RETURN'
  or resolved#>>'{document,focus,id}'is distinct from replacement::text
  or resolved#>>'{document,focus,page_offset}'is null then raise exception 'CP7_RETURN_CORRECTION_SOURCE_UNAVAILABLE';end if;
 result:=jsonb_build_object('contract_version','cp7.sales-return-correction.v1','kind','COMMITTED_OUTCOME','action','RETURN_CORRECT',
  'request_id',p_request,'sale_id',h.id,'row_version',h.row_version::text,'status',h.status,
  'original_return_id',r.id,'original_return_status','REVERSED','return_id',replacement,'return_status','POSTED',
  'return_page_offset',(resolved#>>'{document,focus,page_offset}')::integer,
  'link',cp7_sales_return_correction.link_value(link),'production_go',false);
 update cp7_sales_return_correction.requests set response=result where actor=auth.uid()and request_id=p_request;
 return result;
end $function$

cp7_sales_return_correction.reverse_sale:
CREATE OR REPLACE FUNCTION cp7_sales_return_correction.reverse_sales_return(p_return_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.sales_returns%rowtype;
  s erp.sales_headers%rowtype;
  r record;
  v_journal uuid;
  v_expected numeric(24,6);
  v_paid numeric(20,2);
  v_total numeric(20,2);
  v_po uuid;
begin
 perform cp7_sales_return_correction.require_context();
  perform erp.require_owner_admin();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  perform erp.require_owner_admin();
  perform cp7_credit.native_source_enter('RETURN_REVERSE',p_return_id);
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan reversal retur penjualan wajib diisi'; end if;

  select * into h from erp.sales_returns where id=p_return_id for update;
  if h.id is null then raise exception 'Retur penjualan tidak ditemukan'; end if;
  if h.status='REVERSED' then return; end if;
  if h.status<>'POSTED' then raise exception 'Hanya retur penjualan POSTED yang dapat direverse'; end if;
  select * into s from erp.sales_headers where id=h.sale_id for update;
  if s.id is null or s.status='REVERSED' then raise exception 'Penjualan sumber retur tidak aktif'; end if;

  for v_po in
    select distinct fl.po_id
    from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is not null order by fl.po_id
  loop
    perform erp.assert_po_hpp_target_book_v2620e(v_po);
  end loop;

  for r in
    select distinct fl.product_id
    from erp.sales_return_items i
    join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
    order by fl.product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  select round(coalesce(sum(i.refund_amount),0),2)
  into v_expected
  from erp.sales_return_items i
  where i.return_id=h.id;
  select id into v_journal from erp.journal_entries
  where source_type='SALES_RETURN' and source_id=h.id and status='POSTED'
  order by posting_at desc,id desc limit 1;
  if v_expected>0.005 and v_journal is null then
    raise exception 'Jurnal retur penjualan tidak ditemukan; reversal dibatalkan agar piutang/HPP tidak rusak';
  end if;

  for r in
    select fm.id,fm.qty_signed,fl.cached_qty_pcs
    from erp.fg_stock_movements fm
    join erp.sales_return_items i on i.id=fm.source_id
    join erp.fg_lots fl on fl.id=fm.lot_id
    where i.return_id=h.id and fm.source_type='SALES_RETURN_ITEM'
      and fm.movement_type='SALE_RETURN'
      and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=fm.id)
    order by fm.physical_at desc,fm.id desc
  loop
    if r.cached_qty_pcs<r.qty_signed then
      raise exception 'Barang dari retur ini sudah dipakai/dijual lagi. Reverse transaksi downstream dulu sebelum membatalkan retur.';
    end if;
    perform cp7_sales_return_correction.reverse_fg_movement(r.id,p_reason);
  end loop;

  if v_journal is not null then perform cp7_sales_return_correction.reverse_journal(v_journal,p_reason); end if;
  update erp.sales_returns set status='REVERSED' where id=h.id;

  for r in
    select distinct fl.product_id
    from erp.sales_return_items i
    join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
    order by fl.product_id
  loop
    perform erp.sync_non_po_product_hpp_to_gl_v2620f(
      r.product_id,((h.physical_at AT TIME ZONE 'Asia/Jakarta'::text))::date,'SALES_RETURN_REVERSAL',h.id,
      'Reverse Sales return '||h.id::text||': '||p_reason
    );
  end loop;

  select erp.sale_net_total(s.id)::numeric(20,2) into v_total;
  select coalesce(sum(amount),0)::numeric(20,2) into v_paid
  from erp.sales_payments where sale_id=s.id and status='POSTED';
  perform cp7_credit.source_operation_native_reconcile_v1('RETURN_REVERSE',p_return_id);
  v_paid:=cp7_credit.current_effective_paid(s.id);
  update erp.sales_headers
  set status=case when v_paid=v_total then 'PAID' when v_paid>0 and v_paid<v_total then 'PARTIAL_PAID' else 'POSTED' end
  where id=s.id;

  for v_po in
    select distinct fl.po_id
    from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is not null order by fl.po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(v_po);
    perform erp.sync_po_hpp_to_gl(v_po,((h.physical_at AT TIME ZONE 'Asia/Jakarta'::text))::date);
    perform erp.refresh_po_hpp_gl_baseline(v_po);
    perform erp.assert_po_hpp_target_book_v2620e(v_po);
  end loop;
  insert into erp.audit_logs(entity_type,entity_id,action,changed_by,change_reason)
  values('sales_returns',h.id,'REVERSE',erp.current_app_user_id(),p_reason);
  perform cp7_credit.native_source_complete('RETURN_REVERSE',p_return_id);
  perform erp.require_owner_admin();
end
$function$

erp.post_sales_return(uuid):
CREATE OR REPLACE FUNCTION erp.post_sales_return(p_return_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.sales_returns%rowtype;
  s erp.sales_headers%rowtype;
  r record;
  v_refund numeric(24,6):=0;
  v_sold_qty integer;
  v_prior_returned integer;
  v_current_return integer;
  v_product_sale_value numeric(24,6);
  v_prior_product_refund numeric(24,6);
  v_current_product_refund numeric(24,6);
  v_original_hpp numeric(18,6);
  v_unit_hpp numeric(18,6);
  v_net_total numeric(20,2);
  v_paid numeric(20,2);
  v_delta_cogs numeric(24,6);
  v_delta_fg numeric(24,6);
  v_delta_other numeric(24,6);
  v_target_hpp numeric(24,6);
  v_target_other numeric(24,6);
  v_book_hpp numeric(24,6);
  v_book_other numeric(24,6);
  v_lines jsonb:='[]'::jsonb;
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  perform erp.require_internal();
  perform cp7_credit.native_return_enter(p_return_id);
  perform erp.require_internal();
  select * into h from erp.sales_returns where id=p_return_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Sales return must be DRAFT'; end if;
  if h.sale_id is null then raise exception 'Native sales return must reference the original sale'; end if;
  select * into s from erp.sales_headers where id=h.sale_id for update;
  if s.id is null or s.status not in('POSTED','PARTIAL_PAID','PAID') then raise exception 'Original sale must be active/posted'; end if;
  if s.customer_id is distinct from h.customer_id then raise exception 'Sales return customer does not match original sale customer'; end if;
  if not exists(select 1 from erp.sales_return_items where return_id=h.id) then raise exception 'Sales return has no lines'; end if;

  for r in
    select distinct fl.product_id
    from erp.sales_return_items i
    join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
    order by fl.product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  for r in
    select * from erp.sales_return_items where return_id=h.id
    order by product_id,location_id,quality_grade,lot_id,id
  loop
    if r.lot_id is null then raise exception 'Sales return line requires original FG lot'; end if;
    if not exists(select 1 from erp.fg_lots fl where fl.id=r.lot_id and fl.product_id=r.product_id) then raise exception 'Sales return lot does not belong to selected product'; end if;

    insert into erp.fg_inventory_balances(product_id,location_id,quality_grade,cached_qty_pcs)
    values(r.product_id,r.location_id,r.quality_grade,0)
    on conflict(product_id,location_id,quality_grade) do nothing;
    perform 1 from erp.fg_inventory_balances
    where product_id=r.product_id and location_id=r.location_id and quality_grade=r.quality_grade
    for update;
    perform 1 from erp.fg_lots where id=r.lot_id for update;

    -- Eligibility belongs to the selected allocation. Receipt destination is
    -- independently validated and may be another active FG warehouse.
    select a.qty_pcs,a.unit_hpp_snapshot into v_sold_qty,v_original_hpp
    from erp.sale_stock_allocations a join erp.sales_items si on si.id=a.sale_item_id
    where a.id=r.sale_stock_allocation_id and si.sale_id=h.sale_id
      and si.product_id=r.product_id and a.lot_id=r.lot_id;
    if v_sold_qty is null or v_sold_qty<=0 or v_original_hpp is null then
      raise exception 'AH_RETURN_ALLOCATION_SOURCE_MISMATCH';
    end if;

    v_unit_hpp:=coalesce(erp.lock_current_hpp_per_pcs(r.lot_id),v_original_hpp);
    select coalesce(sum(sri.qty_pcs),0)::integer into v_prior_returned
    from erp.sales_return_items sri join erp.sales_returns sr on sr.id=sri.return_id
    where sr.sale_id=h.sale_id and sr.id<>h.id and sr.status='POSTED'
      and sri.sale_stock_allocation_id=r.sale_stock_allocation_id;
    select coalesce(sum(sri.qty_pcs),0)::integer into v_current_return
    from erp.sales_return_items sri
    where sri.return_id=h.id and sri.sale_stock_allocation_id=r.sale_stock_allocation_id;
    if v_prior_returned+v_current_return>v_sold_qty then
      raise exception 'AH_RETURN_EXCEEDS_ORIGINAL_ALLOCATION: Sales return exceeds quantity originally sold for this allocation. Sold %, prior returned %, current return %',v_sold_qty,v_prior_returned,v_current_return;
    end if;

    select coalesce(sum(si.line_total),0) into v_product_sale_value
    from erp.sales_items si where si.sale_id=h.sale_id and si.product_id=r.product_id;
    select coalesce(sum(sri.refund_amount),0) into v_prior_product_refund
    from erp.sales_return_items sri join erp.sales_returns sr on sr.id=sri.return_id
    where sr.sale_id=h.sale_id and sr.id<>h.id and sr.status='POSTED' and sri.product_id=r.product_id;
    select coalesce(sum(sri.refund_amount),0) into v_current_product_refund
    from erp.sales_return_items sri where sri.return_id=h.id and sri.product_id=r.product_id;
    if v_prior_product_refund+v_current_product_refund>v_product_sale_value then
      raise exception 'Refund exceeds original net sale value for product. Sold value %, prior refund %, current refund %',v_product_sale_value,v_prior_product_refund,v_current_product_refund;
    end if;

    update erp.sales_return_items set unit_hpp_snapshot=v_unit_hpp where id=r.id;
    perform erp.post_fg_movement(r.product_id,r.lot_id,r.location_id,r.quality_grade,
      'SALE_RETURN',r.qty_pcs,v_unit_hpp,h.customer_id,'SALES_RETURN_ITEM',r.id,
      h.physical_at,'Customer sales return',false);
    v_refund:=v_refund+r.refund_amount;
  end loop;

  select greatest(erp.sale_net_total(h.sale_id)-v_refund,0)::numeric(20,2) into v_net_total;
  select coalesce(sum(sp.amount),0)::numeric(20,2) into v_paid
  from erp.sales_payments sp where sp.sale_id=h.sale_id and sp.status='POSTED';
  v_paid:=cp7_credit.native_return_guard(h.id,v_refund,v_net_total,v_paid);
  if v_paid>v_net_total then
    raise exception 'Retur ini membuat pembayaran customer melebihi nilai penjualan tersisa. Nilai setelah retur %, sudah dibayar %. Reverse/koreksi pembayaran customer dulu agar kelebihan bayar tidak hilang dari pembukuan.',v_net_total,v_paid;
  end if;

  update erp.sales_returns set status='POSTED' where id=h.id;
  if abs(v_refund)>0.005 then
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('mapping_key','SALES_REVENUE','debit',round(v_refund,2),'credit',0,'customer_id',h.customer_id),
      jsonb_build_object('mapping_key','AR_CUSTOMER','debit',0,'credit',round(v_refund,2),'customer_id',h.customer_id));
  end if;

  for r in
    select distinct fl.product_id
    from erp.sales_return_items i
    join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
    order by fl.product_id
  loop
    select round(t.fg_value-b.fg_value,2),
      round(t.cogs_value-b.cogs_value,2),
      round(t.other_out_value-b.other_out_value,2)
    into v_delta_fg,v_delta_cogs,v_delta_other
    from erp.compute_non_po_product_hpp_targets_v2620f(r.product_id) t
    cross join lateral erp.compute_non_po_product_hpp_book_v2620f(r.product_id) b;
    if abs(v_delta_fg+v_delta_cogs+v_delta_other)>0.005 then
      raise exception 'Return non-PO HPP delta does not conserve source value for product %: fg %, cogs %, other %',
        r.product_id,v_delta_fg,v_delta_cogs,v_delta_other;
    end if;
    if abs(v_delta_fg)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_fg>0
        then jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_delta_fg,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,
          'credit',abs(v_delta_fg),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
    if abs(v_delta_cogs)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_cogs>0
        then jsonb_build_object('mapping_key','COGS','debit',v_delta_cogs,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','COGS','debit',0,
          'credit',abs(v_delta_cogs),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
    if abs(v_delta_other)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_other>0
        then jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_delta_other,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,
          'credit',abs(v_delta_other),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
  end loop;

  for r in
    select distinct fl.po_id
    from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is not null order by fl.po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(r.po_id);
    select
      round(coalesce(t.cogs_value,0),2)-st.cogs_value,
      round(coalesce(t.fg_value,0),2)-st.fg_value,
      (round(coalesce(t.hpp_total_cost,0),2)-round(coalesce(t.fg_value,0),2)
        -round(coalesce(t.cogs_value,0),2))-st.other_out_value,
      round(coalesce(t.hpp_total_cost,0),2),
      round(coalesce(t.hpp_total_cost,0),2)-round(coalesce(t.fg_value,0),2)-round(coalesce(t.cogs_value,0),2),
      st.hpp_total_cost,st.other_out_value
    into v_delta_cogs,v_delta_fg,v_delta_other,
      v_target_hpp,v_target_other,v_book_hpp,v_book_other
    from erp.po_hpp_gl_state st
    cross join lateral erp.compute_po_hpp_gl_targets_v2620d(r.po_id) t
    where st.po_id=r.po_id for update of st;
    if v_delta_cogs>0.005 or v_delta_fg<-0.005
       or abs(v_delta_cogs+v_delta_fg+v_delta_other)>0.005
       or v_target_hpp is distinct from v_book_hpp then
      raise exception 'Sales-return cumulative HPP target does not conserve PO value %. dc %, df %, do %, target/book hpp %/%',
        r.po_id,v_delta_cogs,v_delta_fg,v_delta_other,v_target_hpp,v_book_hpp;
    end if;
    if abs(v_delta_cogs)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_cogs>0 then
        jsonb_build_object('mapping_key','COGS','debit',v_delta_cogs,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','COGS','debit',0,'credit',abs(v_delta_cogs),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
    if abs(v_delta_fg)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_fg>0 then
        jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_delta_fg,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',abs(v_delta_fg),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
    if abs(v_delta_other)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_other>0 then
        jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_delta_other,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',abs(v_delta_other),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
  end loop;
  if jsonb_array_length(v_lines)>=2 then
    perform cp7_credit.post_return_journal('SALES_RETURN',h.id,(h.physical_at AT TIME ZONE 'Asia/Jakarta')::date,
      'Sales return from customer · cumulative exact HPP target',v_lines);
  end if;
  perform cp7_credit.flush_opening_return_hpp_v1(h.id);
  v_paid:=cp7_credit.native_return_complete(h.id,v_refund,v_net_total);
  perform erp.require_internal();

  for r in
    select distinct fl.product_id
    from erp.sales_return_items i
    join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
    order by fl.product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  update erp.sales_headers
  set status=case when v_paid=v_net_total then 'PAID' when v_paid>0 and v_paid<v_net_total then 'PARTIAL_PAID' else 'POSTED' end
  where id=h.sale_id;
  for r in
    select distinct fl.po_id
    from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is not null order by fl.po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(r.po_id);
    perform erp.assert_po_hpp_target_book_v2620e(r.po_id);
  end loop;
  perform cp7_credit.native_return_leave(h.id);
  perform erp.require_internal();
end
$function$
